const CHAPTERS: VizChapter[] = [{"id":"clang-u01","subj":"clang","title":"指针与地址运算","summary":"","concepts":[{"id":"clang-u01/01-address-and-decay","file":"01-address-and-decay.md","title":"地址、指针与数组退化","kind":"stack","secs":[{"h":"一、指针的本质：带类型的地址","s":"内存是一排按字节编号的格子，编号就是地址。指针是一个变量，里面存的正是这样一个编号。","c":{"lang":"c","code":"int x = 42;\nint *p = &x;      /* p 里存的是 x 的地址 */"}},{"h":"二、数组退化（decay）","s":"数组名在大多数表达式中会转换（退化）为「指向首元素的指针」：","c":{"lang":"c","code":"int a[5];\nint *p = a;        /* 等价于 &a[0] */"}},{"h":"三、函数参数的退化陷阱","s":"数组作函数参数时，会退化为指针，长度信息彻底丢失：","c":{"lang":"c","code":"void f(int a[5]) {          /* 编译后实际是 int *a */\n    printf(\"%zu\\n\", sizeof(a));   /* 8，不是 20 */\n}"}},{"h":"四、指针相减与比较","s":"","c":{"lang":"c","code":"int a[5];\nptrdiff_t d = &a[4] - &a[1];   /* 3（元素个数） */"}},{"h":"五、NULL 与空指针","s":"","c":{"lang":"c","code":"int *p = NULL;      /* 不指向任何对象 */\nif (p) { ... }      /* 等价于 p != NULL */"}},{"h":"六、void ：通用指针","s":"void 是「无类型指针」，可以与其他对象指针隐式互相转换（C 中不需要强转）：","c":{"lang":"c","code":"void *raw = malloc(100);   /* C 中无需 (int*) 强转 */\nint *arr = raw;"}},{"h":"七、sizeof 与指针：六个必须秒答的结果","s":"sizeof 是编译期运算符，结果只由类型决定，不看运行时的值。指针相关的那几个结果之所以常考，是因为它们各自卡在「数组退化的边界」上：","c":null}]},{"id":"clang-u01/02-multilevel-and-function-pointer","file":"02-multilevel-and-function-pointer.md","title":"多级指针、数组指针与函数指针","kind":"compare","secs":[{"h":"一、多级指针：指针的指针","s":"这与「函数要修改 int 就传 int 」是同一条规则递归一次的结果。链表头插/删头节点也依赖它。","c":{"lang":"c","code":"int x = 42;\nint *p = &x;       /* 一级：指向 int */\nint **pp = &p;     /* 二级：指向「指向 int 的指针」 */"}},{"h":"二、数组指针 vs 指针数组（最经典的易混点）","s":"对比：int p = m; 是错的——二维数组不是「指针的指针」，它是「数组的数组」，内存连续。","c":{"lang":"c","code":"int *arr[5];    /* 指针数组：5 个元素的数组，每个元素是 int* */\nint (*par)[5];  /* 数组指针：一个指针，指向「含 5 个 int 的数组」 */"}},{"h":"三、函数指针","s":"括号不可省：int fp(int, int) 是「返回 int 的函数」。","c":{"lang":"c","code":"int (*fp)(int, int);       /* 指向「接受两个 int、返回 int」的函数 */"}},{"h":"四、函数指针与 dlsym/动态加载","s":"运行时按名字取函数（插件系统）：","c":{"lang":"c","code":"void *h = dlopen(\"./libplug.so\", RTLD_LAZY);\nvoid (*init)(void) = dlsym(h, \"plug_init\");\ninit();"}}]},{"id":"clang-u01/03-const-and-dangling","file":"03-const-and-dangling.md","title":"const 修饰指针、野指针与悬垂指针","kind":"flow","secs":[{"h":"一、const 修饰指针的三种形态","s":"C 里要真正的编译期常量，用 #define 或 enum。","c":{"lang":"c","code":"int x = 1, y = 2;\nconst int *p1 = &x;\np1 = &y;        /* OK */\n/* *p1 = 5;     /* 编译错误 */\n\nint * const p2 = &x;\n*p2 = 5;        /* OK */\n/* p2 = &y;     /* 编译错误 */"}},{"h":"二、野指针（wild pointer）","s":"","c":{"lang":"c","code":"int *p = NULL;         /* 好习惯 */"}},{"h":"三、悬垂指针（dangling pointer）","s":"注意：free 不会修改 p 的值，p 仍指向那块已归还的内存。这也解释了为什么「重复 free 同一指针」是双重释放（double free）——会破坏分配器的元数据。","c":{"lang":"c","code":"int *p = malloc(sizeof(int));\nfree(p);\n*p = 10;        /* UB：use-after-free */\np = NULL;       /* 规范做法：置空，重复 free(NULL) 是安全的 */"}},{"h":"四、字符串字面量的类型陷阱","s":"","c":{"lang":"c","code":"char *s = \"hello\";      /* 危险：字面量在只读段，写它 → 段错误 */\ns[0] = 'H';             /* UB / SIGSEGV */\n\nconst char *s2 = \"hello\";   /* 正确：类型就表达了只读 */\nchar buf[] = \"hello\";       /* 正确：buf 是栈上可写副本 */\nbuf[0] = 'H';               /* OK */"}},{"h":"五、越界为什么「有时不崩」","s":"指针算术无边界检查。a[5] 越界读写栈上的相邻变量——可能读到别的变量、可能破坏返回地址：","c":null}]},{"id":"clang-u01/04-pointer-practical-recipes","file":"04-pointer-practical-recipes.md","title":"C 指针实战手记：凯喵的十二次段错误现场还原","kind":"flow","secs":[{"h":"开场：指针不是「指向」，是「地址 + 类型」","s":"指针的值是一个地址，指针的类型决定两件事：从这个地址读多少字节、以及指针运算的步长。","c":{"lang":"c","code":"int* p;      // 值：某个地址；类型：int*，解引用读 4 字节，p+1 前进 4 字节\nchar* q;     // 解引用读 1 字节，q+1 前进 1 字节"}},{"h":"收尾：指针的三个问题","s":"凯喵最后总结：所有指针 bug 都能归到三个问题的某一个。","c":null}]}],"exams":[{"kind":"choice","q":"数组退化的例外","stem":"对于 int a[10];，下列哪些表达式中 a 不会退化为指针？（多选） A. sizeof(a) B. &a C. a + 1 D. a[3]","opts":[{"k":"A","t":"sizeof(a)"},{"k":"B","t":"&a"},{"k":"C","t":"a + 1"},{"k":"D","t":"a[3]"}],"ans":"AB","why":"数组名退化的例外只有 sizeof 与取地址 & 两个上下文。sizeof(a) 得整个数组字节数；&a 得数组指针 int()[10]。a + 1 与 a[3]（等价 (a+3)）都发生退化为 int。"},{"kind":"output","q":"三个地址与两次步长","stem":"写出下面程序的输出（假设 int 为 4 字节、指针为 8 字节）： c int a[5]; printf(\"%zu %zu\\n\", sizeof(a), sizeof(&a[0])); printf(\"%td %td\\n\", (a + 1) - a, (char )(&a + 1) - (char )&a);","opts":[],"ans":"20 8 1 20","why":"sizeof(a) 是整数组 5×4=20；&a[0] 是指针，8 字节。(a+1)-a 按元素计为 1；&a 是数组指针，+1 前进整个数组 20 字节，转 char 相减得 20。"},{"kind":"choice","q":"const 的位置","stem":"int const p = &x; 之后，下列哪项是非法的？ A. p = 10; B. p = &y; C. printf(\"%d\", p);","opts":[{"k":"A","t":"p = 10;"},{"k":"B","t":"p = &y;"},{"k":"C","t":"printf 读取 p"}],"ans":"B","why":"const 在 右侧，锁住的是指针本身：p 不能重新指向，但 p 可改。所以改 p 与读取都合法，p = &y; 编译错误。"},{"kind":"fix_error","q":"让函数真正分配内存","stem":"下面的函数无法把分配到的内存交给调用方，且存在泄漏。指出问题并改正： c void alloc(int p, size_t n) { p = malloc(n sizeof(int)); } int main(void) { int buf = NULL; alloc(buf, 10); / buf 仍是 NULL / }","opts":[],"ans":"void alloc(int out, size_t n) { out = malloc(n sizeof(int)); } int main(void) { int buf = NULL; alloc(&buf, 10); if (!buf) { return 1; } free(buf); buf = NULL;…","why":"参数 int p 是值传递，函数内 p 只是实参的副本，给它赋值不影响调用方的 buf；且副本丢失导致内存泄漏。要修改调用方的指针，必须传指针的地址（二级指针 int out），在函数内 out = malloc(...)。"},{"kind":"coding","q":"反转字符串（双指针原地交换）","stem":"给定一个字符数组，原地反转它。要求空间复杂度 O(1)，使用双指针从两端向中间交换。","opts":[],"ans":"void reverseString(char s, int sSize) { int i = 0, j = sSize - 1; while (i < j) { char t = s[i]; s[i++] = s[j]; s[j--] = t; } }","why":"经典双指针：i 从头、j 从尾，交换后相向移动直到相遇。考察指针/下标的边界控制与原地交换。"},{"kind":"coding","q":"移动零（快慢指针）","stem":"把数组中所有 0 移到末尾，同时保持非零元素的相对顺序，要求原地操作。","opts":[],"ans":"void moveZeroes(int nums, int numsSize) { int slow = 0; for (int fast = 0; fast < numsSize; fast++) { if (nums[fast] != 0) { int t = nums[slow]; nums[slow++] =…","why":"快慢指针：fast 遍历，遇到非零就与 slow 位置交换，slow 只在写入后前进。交换写法天然把 0 推到后面，无需额外清零。"}],"works":[{"h":"把数组名当指针用 sizeof","d":"sizeof(a) 在数组所在作用域得整个数组大小（如 20），但一旦 a 退化为函数参数，sizeof(a) 变成指针大小（8）。正确写法：把长度作为参数显式传入 void f(int a, size_t n)。"},{"h":"混淆 a、&a、&a[0] 的步长","d":"三者地址值相同，但 &a 的类型是 int ()[N]，&a + 1 会跳过整个数组（N 个元素），而 a + 1 只跳过 1 个元素。正确写法：需要逐元素遍历用 a + i；需要「跳到数组之后」用 &a + 1。"},{"h":"二维数组用 int","d":"接收 —— int m[3][4] 的内存是连续的「数组的数组」，不是「指针的指针」。int p = m; 类型不兼容且解引用会错。正确写法：用数组指针 int (p)[4] = m;，或函数参数写 void f(int p[][4])。"},{"h":"free 之后不置 NULL","d":"free(p) 只是归还内存，p 的值不变，仍指向已释放区域；再次 free(p) 就是 double free，会破坏分配器。正确写法：free(p); p = NULL;——free(NULL) 是安全空操作。"},{"h":"返回局部变量地址","d":"int f(void){ int x = 1; return &x; } 返回后栈帧失效，得到悬垂指针。正确写法：返回值（拷贝）、返回 static（注明不可重入）、或让调用方传入缓冲区。"},{"h":"把 char s = \"abc\" 当可写缓冲","d":"字符串字面量位于只读段，s[0] = 'X' 会触发段错误。正确写法：需要修改就用数组副本 char buf[] = \"abc\";（栈上可写），只读场景声明为 const char s = \"abc\";。"},{"h":"用指针相减求字节数","d":"指针相减得到的是元素个数（类型 ptrdiff_t），不是字节数。&a[4] &a[1] 是 3。正确写法：要字节数先转 char ：(char)&a[4] (char)&a[0]。"},{"h":"跨对象比较指针大小","d":"p < q 只在两者指向同一数组（含尾后位置）时有定义，否则是 UB。正确写法：不同对象之间只用 == / != 判断是否同一对象，不要比大小。"}],"asks":[{"q":"指针和数组到底是不是一回事？","a":"不是。 C 标准里数组是独立类型。 - 相同点：数组名在大多数表达式中退化为指向首元素的指针，所以 a[i] 与 (a+i) 等价。 - 不同点： 1. sizeof(a) 得整个数组大小，sizeof(指针) 恒为平台字长（64 位下 8）。 2. &a 的类型是 T()[N]，步长是整数组。 3. 数组名不可赋值，指针可以。 4. 数组有确定长度（是类型的一部分），退化成指针后长度丢失——这就…","fu":["a[i] 是怎么被编译器翻译的？为什么 i[a] 也合法？","C99 的变长数组（VLA）和这个有什么关系？"],"tag":"通用/腾讯"},{"q":"指针算术在底层是怎么实现的？p + n 到底加了什么？","a":"编译器把 p + n 翻译为「地址 + n × sizeof(p)」的字节偏移，即 (char)p + n sizeof(p)。 - 所以 p+1 前进的是元素不是字节。 - void 上的算术是未定义的（sizeof(void) 不存在），GCC 扩展按 1 处理但不可移植。 - 指针相减得到的是元素个数（ptrdiff_t），要字节数必须先转 char。 - 越界指针运算、跨对象相减/比较都是…","fu":["为什么指针相减只允许同一数组内？","编译器如何利用「指针不越界」这一假设做优化？"],"tag":"通用/汇编/系统向"},{"q":"函数指针有什么实际用途？在 C 里怎么实现多态？","a":"用途 1. 回调：qsort/bsearch 的比较器。 2. 虚表手工模拟：把函数指针放进结构体，实现运行时分派——这是 C 里的「多态」。 3. 跳转表/状态机：handler_t table[] 用下标分派，比 switch 更易扩展。 4. 插件注册与 dlsym 动态加载。 C 实现多态的最小骨架 c typedef struct Shape { double (area)(const…","fu":["虚表放在对象里还是类型里？哪种更省内存？","函数指针调用能被内联吗？为什么？"],"tag":"通用/嵌入式"},{"q":"悬垂指针和内存泄漏哪个更危险？怎么系统性防护？","a":"危害维度不同，但悬垂（含 use-after-free / double free）更危险： - 内存泄漏：只涨内存，不损坏数据，可观测可定位。 - 悬垂：属于 UB，可能静默破坏数据或崩溃，且可被利用为安全漏洞（堆利用、控制流劫持）。 系统性防护 1. 所有权约定：谁分配谁释放；释放后所有别名失效，置 NULL。 2. 单一出口：错误路径统一 goto cleanup，保证释放配对。 3. 工具…","fu":["为什么 free(p) 之后 p 的值不变？","ASan 是怎么在常量时间发现 use-after-free 的？"],"tag":"安全向/腾讯"}]},{"id":"clang-u02","subj":"clang","title":"内存与动态分配（malloc/free）","summary":"","concepts":[{"id":"clang-u02/01-stack-vs-heap","file":"01-stack-vs-heap.md","title":"栈与堆：两种生命周期","kind":"stack","secs":[{"h":"一、进程内存分区（高地址 → 低地址）","s":"","c":{"lang":"text","code":"+---------------------+  高地址\n|   命令行参数/环境变量  |\n+---------------------+\n|        栈 (stack)     |  ↓ 向下增长：局部变量、参数、返回地址\n+---------------------+\n|         ↓             |\n|        ...            |\n|         ↑             |\n+---------------------+\n…"}},{"h":"二、栈的特点","s":"","c":null},{"h":"三、堆的特点","s":"","c":null},{"h":"四、malloc 的真实成本","s":"malloc 并不每次都向内核要内存。glibc 的分配策略：","c":{"lang":"c","code":"malloc(1)   /* 实际占用通常 ≥ 32 字节（头部 + 对齐到 16 字节） */"}},{"h":"五、碎片","s":"举个具体例子：先分配 1000 个 64 KB 的块，再隔一个 free 一个。此时空闲总量有 32 MB，却被切成 500 个互不相邻的 64 KB 空洞——再申请 1 MB 就会失败。这就是「总量够却拿不出来」，也是按尺寸分级的内存…","c":null},{"h":"六、与 C++ 的边界（面试常问）","s":"","c":null}]},{"id":"clang-u02/02-malloc-family","file":"02-malloc-family.md","title":"malloc / calloc / realloc / free 的契约","kind":"flow","secs":[{"h":"一、四个函数的语义","s":"","c":{"lang":"c","code":"int *a = malloc(10 * sizeof(int));   /* 内容不确定 */\nif (!a) { /* 必须判空 */ }\nint *b = calloc(10, sizeof(int));    /* 10 个 0 */"}},{"h":"二、realloc 的正确写法（高频考点）","s":"realloc 可能原地扩展，也可能分配新块 + 拷贝 + 释放旧块，所以它返回的是新地址，旧指针可能失效。","c":{"lang":"c","code":"/* ❌ 错误：一旦 realloc 失败返回 NULL，原指针 p 被覆盖 → 内存泄漏 */\np = realloc(p, new_n);\n\n/* ✅ 正确：用临时变量接，成功后再赋值 */\nvoid *tmp = realloc(p, new_n);\nif (!tmp) {\n    /* 原 p 仍然有效，需自行释放或向上抛错 */\n    free(p);\n    return NULL;\n…"}},{"h":"三、free 的契约与陷阱","s":"","c":{"lang":"c","code":"int *p = malloc(sizeof(int));\nfree(p);        /* p 的值（地址）不变，仍指向该块 —— 但块已归还 */\n/* *p = 5;      /* use-after-free，UB */\np = NULL;       /* 规范做法：free 后立即置空 */"}},{"h":"四、malloc 失败的处理","s":"正解之一是用 calloc（自带溢出检查），或显式检查：","c":{"lang":"c","code":"int *a = malloc(n * sizeof(int));\nif (!a) {\n    fprintf(stderr, \"out of memory\\n\");\n    return NULL;        /* 向上传播，不要继续用 a */\n}"}},{"h":"五、malloc(0) 与对齐","s":"","c":null},{"h":"六、C 中不需要强转","s":"C 中 void 可隐式转换为任意对象指针。C++ 中则必须强转（C++ 不允许 void 隐式转 T）。所以看到「C 代码里到处写 (int)malloc(...)」，通常是 C++ 程序员写的 C 代码。","c":{"lang":"c","code":"int *a = malloc(n * sizeof(int));     /* C：无需 (int*) 强转 */"}}]},{"id":"clang-u02/03-leaks-and-tooling","file":"03-leaks-and-tooling.md","title":"内存泄漏、调试工具与内存池","kind":"stack","secs":[{"h":"一、什么是内存泄漏","s":"","c":{"lang":"text","code":"栈/全局：p ─╳    （p 被覆盖或作用域结束）\n堆：      [==============]  ← 失去引用，永不释放"}},{"h":"二、六大典型成因","s":"1. 忘记 free：最直接。","c":{"lang":"c","code":"int f(void) {\n    char *buf = malloc(1024);\n    if (some_error()) {\n        return -1;          /* ❌ buf 泄漏 */\n    }\n    free(buf);\n    return 0;\n}"}},{"h":"三、碎片","s":"","c":null},{"h":"四、调试工具","s":"","c":null},{"h":"五、内存池（pool allocator）","s":"","c":{"lang":"c","code":"typedef struct Block { struct Block *next; } Block;\n\ntypedef struct {\n    Block  *free_list;\n    void   *slab;\n    size_t  block_size, capacity, used;\n} Pool;\n\nvoid *pool_alloc(Pool *p) {\n…"}},{"h":"六、C 的替代方案（面试加分）","s":"","c":null}]},{"id":"clang-u02/04-malloc-practical-recipes","file":"04-malloc-practical-recipes.md","title":"C 内存管理实战手记：凯喵的十二次「跑十分钟就 OOM」","kind":"flow","secs":[{"h":"开场：栈和堆的分工不是「快慢」，是「生命周期」","s":"栈：函数调用时自动分配、返回时自动回收，大小固定（通常几 MB），分配就是移动栈指针（一条指令）。堆：手动分配、手动释放，大小受限于物理内存，分配要走分配器算法。","c":{"lang":"c","code":"void f(void) {\n    int a[10];              // 栈：函数返回自动回收\n    int* p = malloc(10 * sizeof(int));   // 堆：需要手动 free\n    // ...\n    free(p);\n}"}},{"h":"收尾：内存管理的三条纪律","s":"凯喵最后总结：C 的内存问题看起来种类繁多，但归纳起来只有三条纪律。","c":null}]}],"exams":[{"kind":"choice","q":"哪个函数会清零","stem":"下列哪个函数申请的内存保证初始化为 0？ A. malloc B. calloc C. realloc D. alloca","opts":[{"k":"A","t":"malloc"},{"k":"B","t":"calloc"},{"k":"C","t":"realloc"},{"k":"D","t":"alloca"}],"ans":"B","why":"只有 calloc 保证清零。malloc 与 realloc 都是脏数据（realloc 原数据保留、新增部分不清零）；alloca 是栈分配，内容不确定。"},{"kind":"output","q":"malloc 与 calloc 的初值","stem":"下面程序中，a[0] 与 b[0] 的输出分别是什么？（malloc 返回的内存内容是脏数据） c int a = calloc(3, sizeof(int)); int b = malloc(3 sizeof(int)); printf(\"a[0]=%d\\n\", a[0]); printf(\"b 内容是否确定 = %s\\n\", \"否\");","opts":[],"ans":"a[0]=0 b 内容是否确定 = 否","why":"calloc 清零所以 a[0] 必为 0（这也是本示例能可靠断言的原因）；malloc 的内容不确定，任何具体值都不可依赖——所以示例只能断言「不确定」这个事实，不能断言 b[0] 的数值。这本身就是重要一课：不要对未初始化内存的取值做假设。"},{"kind":"fix_error","q":"修掉 realloc 的泄漏","stem":"下面的扩容函数在 realloc 失败时会泄漏原内存。指出原因并改正： c int grow(int p, size_t new_n) { p = realloc(p, new_n sizeof(int)); if (!p) return -1; return 0; }","opts":[],"ans":"int grow(int pp, size_t new_n) { if (new_n > SIZE_MAX / sizeof(int)) return -1; void tmp = realloc(pp, new_n sizeof(int)); if (!tmp) return -1; / 原 pp 仍有效，由调用方决…","why":"p = realloc(p, ...) 在失败时把 NULL 写回 p，原内存地址彻底丢失，既泄漏又无法继续使用。改正要点有二：① 用临时变量接收返回值，成功后再赋值；② 需要修改调用方的指针，参数应为二级指针 int pp（与 clang-u01 的规则一致）。顺带补上乘法溢出检查。"},{"kind":"choice","q":"free 之后的行为","stem":"关于 free(p)，下列说法正确的是？ A. free 会把 p 置为 NULL B. free(NULL) 会导致崩溃 C. free 后 p 的值不变，仍指向已归还的内存 D. free 会把内存立即归还给操作系统","opts":[{"k":"A","t":"free 会置 p 为 NULL"},{"k":"B","t":"free(NULL) 会崩溃"},{"k":"C","t":"free 后 p 的值不变，是悬垂指针"},{"k":"D","t":"free 会立即归还内存给内核"}],"ans":"C","why":"free 只把块交还分配器，不修改传入的指针变量（C 是值传递），所以 p 成为悬垂指针。free(NULL) 是标准规定的安全空操作。小块 free 后内存进入分配器的空闲链表，通常不归还内核，所以进程 RSS 不下降是正常的。"},{"kind":"coding","q":"合并两个有序数组（原地，从后往前）","stem":"给定两个非递减数组与各自长度，把第二个合并进第一个（第一个数组末尾预留了足够空间）。要求原地完成。","opts":[],"ans":"void merge(int nums1, int nums1Size, int m, int nums2, int nums2Size, int n) { int i = m - 1, j = n - 1, k = m + n - 1; while (j >= 0) { if (i >= 0 && nums1[i]…","why":"从后往前填充避免覆盖尚未处理的 nums1 元素（从前往前则需要额外 O(m) 空间）。考察下标/指针的边界控制——与 memcpy 的重叠区域处理是同一类问题。"},{"kind":"coding","q":"链表反转（指针操作）","stem":"给定单链表头节点，反转整个链表并返回新的头节点。要求原地操作、只使用常数额外空间。","opts":[],"ans":"typedef struct ListNode { int val; struct ListNode next; } ListNode; ListNode reverseList(ListNode head) { ListNode prev = NULL, cur = head; while (cur) { ListN…","why":"三指针迭代：prev/cur/nxt。关键是先保存 cur->next 再改链，否则丢失后半段。这是指针操作最经典的题，也是检验「是否真的理解指针」的标准题。"}],"works":[{"h":"malloc 后不判空","d":"内存不足时 malloc 返回 NULL，直接解引用即崩溃。正确写法：分配后立即 if (!p) { / 处理或向上传播 / }。"},{"h":"realloc 直接赋值给原指针","d":"p = realloc(p, n); 一旦失败返回 NULL，p 被覆盖，原内存永久泄漏。正确写法：void tmp = realloc(p, n); if (!tmp) { ... } p = tmp;。"},{"h":"free 后继续使用（use-after-free）","d":"free(p) 只归还内存，不改 p 的值，p 或 p[i] 是 UB（可能崩溃，也可能静默读到已被复用的数据）。正确写法：free(p); p = NULL;。"},{"h":"重复释放（double free）","d":"对同一块 free 两次会破坏分配器元数据。正确写法：释放后立即置 NULL（free(NULL) 是安全的），或明确所有权让释放只发生一次。"},{"h":"对非 malloc 来源的指针 free","d":"对栈变量地址、全局数组、或 p + 1 这类偏移后的指针调用 free 会破坏堆。正确写法：只 free 分配函数返回的原始地址。"},{"h":"count sizeof(T) 乘法溢出","d":"用户可控的 count 极大时乘法回绕，分配到远小于预期的块，后续写入造成堆溢出（可被利用的安全漏洞）。正确写法：if (count > SIZE_MAX / sizeof(T)) return NULL; 或改用自带溢出检查的 calloc。"},{"h":"大数组放栈上","d":"int a[1000000]; 一次占 4 MB，在默认 1 MB 栈上直接栈溢出。正确写法：改用 malloc，或调大栈（但不要依赖）。"},{"h":"返回局部数组的地址","d":"char f(void){ char buf[64]; return buf; } 返回后栈帧失效，得到悬垂指针。正确写法：改用 malloc（调用方负责释放）、让调用方传入缓冲区、或返回 static（注明不可重入）。"}],"asks":[{"q":"malloc 底层是怎么实现的？为什么 free 之后内存没还给操作系统？","a":"两层结构 1. 分配器层（glibc ptmalloc / jemalloc / tcmalloc）：维护空闲链表与尺寸分级（bins / size classes）。malloc 从这里切分内存，free 只是把块放回链表并尝试与相邻空闲块合并（coalesce）。 2. 系统层：分配器通过 brk/sbrk 调整堆顶 或 mmap 申请新区域。小请求走堆（brk），大请求（默认 ≥128 KB…","fu":["brk 与 mmap 两种方式各自的优缺点？","为什么大块用 mmap？碎片角度怎么解释？"],"tag":"通用/字节"},{"q":"malloc(1) 实际会占用多少内存？为什么？","a":"远不止 1 字节——通常是 16～32 字节（视分配器与平台）。 两个原因 1. 元数据头部：分配器要在块的前面记录大小、是否空闲、链表指针等，free 时才能靠「返回地址 - 头部偏移」找回这些信息。这也是为什么 free 必须传原始返回地址。 2. 对齐要求：返回地址必须满足 max_align_t 对齐（x86-64 通常 16 字节），以保证能存放任何基本类型与多数结构体。块大小会被向上取…","fu":["怎么测量一次 malloc 的真实占用？","内存池为什么能同时减少碎片和分配耗时？"],"tag":"通用/系统向"},{"q":"内存泄漏怎么排查？为什么说它比 use-after-free 更好定位？","a":"排查手段 1. ASan LeakSanitizer：gcc -fsanitize=address -g，退出时打印「泄漏块大小 + 分配点调用栈」。最推荐，CI 可自动化。 2. valgrind：--leak-check=full --show-leak-kinds=all，给出完整调用栈；慢但无需重编译。 3. 堆快照对比：mtrace / heaptrack，适合长跑服务。 4. 代码审计…","fu":["ASan 用什么机制在 O(1) 检测 UAF？","长期运行的服务怎么区分「缓存增长」和「真泄漏」？"],"tag":"通用/安全向"},{"q":"多个 malloc 和一次 malloc 一大块自己切分，怎么选？","a":"一次大块 + 自己切分 = arena/pool 分配，取舍如下。 选池化的场景 - 对象尺寸固定或分类有限，且分配/释放极其频繁（网络包的 buffer、AST 节点、游戏实体）。 - 需要批量释放（整个池一次 free，生命周期统一，比如「一个请求内的所有临时对象」）。 - 追求确定性延迟：池分配是 O(1) 指针操作，无系统调用、无锁竞争（可做 per-thread arena）。 选逐个…","fu":["池化后为什么要显式调用析构/清理函数？","per-thread arena 如何避免跨线程 free 的锁竞争？"],"tag":"后端/腾讯"}]},{"id":"clang-u03","subj":"clang","title":"结构体与联合体","summary":"","concepts":[{"id":"clang-u03/01-memory-layout-and-alignment","file":"01-memory-layout-and-alignment.md","title":"01 · 内存对齐、填充与结构体布局","kind":"stack","secs":[{"h":"一、理论根基：对齐是「硬件契约」","s":"","c":null},{"h":"二、实现机制：手算 sizeof 与填充","s":"经典三步法（以 LP64、x86-64 System V ABI 为例：char=1、short=2、int=4、double=8、指针=8）：","c":{"lang":"text","code":"规则 A：首成员偏移为 0。\n规则 B：成员 offset 取其「声明顺序累计大小，向上圆整到该成员对齐值」。\n规则 C：sizeof 末尾再圆整到「结构体对齐值（=最大成员对齐）」。"}},{"h":"三、offsetof 与 ABI","s":"offsetof(type, member) 返回成员相对结构体首地址的字节偏移（本质是 ((char)&((type)0)->member) - (char)0，标准以宏实现，规避了空指针解引用的 UB）。它在三处不可或缺：","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例：眼见为实","s":"","c":{"lang":"c","code":"#include <stdio.h>\n#include <stddef.h>\n\nstruct Bad  { char a; double d; char b; };\nstruct Good { double d; char a; char b; };\n\nint main(void) {\n    printf(\"sizeof(Bad)=%zu  offset d=%zu b=%zu\\n\",\n           sizeof(struct Bad), offsetof(struct Bad, d), offsetof(struct Bad, b));\n…"}}]},{"id":"clang-u03/02-bitfield-and-union","file":"02-bitfield-and-union.md","title":"02 · 位域与联合体：类型双关的利与刃","kind":"stack","secs":[{"h":"一、位域：方便的「实现定义」特性","s":"位域（bit-field）允许把一个整型成员拆成若干位宽更小的子字段，常用于表示「标志位集合」或紧凑协议字段：","c":{"lang":"c","code":"struct Flags {\n    unsigned int ready : 1;\n    unsigned int mode  : 3;   // 0..7\n    unsigned int prio  : 4;\n};"}},{"h":"二、联合体（union）的本质：重叠存储","s":"union 的所有成员共享同一段内存，大小 = 最大成员的大小（同样受对齐约束）。它是「同一字节既能解释成 A 也能解释成 B」的底层表达。","c":{"lang":"c","code":"union U { int i; float f; };"}},{"h":"三、tagged union：把 UB 关进笼子","s":"既然「裸 union 读非活跃成员」是 UB，安全的做法是配一个「判别标签」组成 tagged union：","c":{"lang":"c","code":"struct Value {\n    enum { I, F, S } tag;       // 显式记录当前活跃成员\n    union {\n        long  i;\n        double f;\n        char  s[32];\n    } u;\n};"}},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例：union 观察 IEEE 754 位模式","s":"","c":{"lang":"c","code":"#include <stdio.h>\n#include <string.h>\n#include <stdint.h>\n\nint main(void) {\n    float f = 1.0f;\n    uint32_t bits;\n    memcpy(&bits, &f, sizeof bits);\n    printf(\"float 1.0 的 IEEE754 位模式 = 0x%08X\\n\", bits);\n…"}}]},{"id":"clang-u03/03-copy-and-ffi","file":"03-copy-and-ffi.md","title":"03 · 拷贝语义、传参/返回优化与柔性数组","kind":"stack","secs":[{"h":"一、结构体赋值：逐成员浅拷贝","s":"C 中结构体是值类型，赋值 a = b; 是逐成员拷贝（memberwise copy），等价于对每个字段做 a.x = b.x;。这与 C++ 的拷贝构造不同——C 没有构造/析构，赋值纯粹是比特层面的逐字段复制。","c":{"lang":"c","code":"struct Buf { char *p; size_t n; };\nstruct Buf a = make_buf(10);\nstruct Buf b = a;     // b.p == a.p，两对象共享同一块内存\nfree(a.p); free(b.p); // double free！a.p 与 b.p 指向同一处"}},{"h":"二、传参与返回：被编译器「隐藏优化」的拷贝","s":"","c":null},{"h":"三、返回局部结构体指针是 UB","s":"返回值（return p;，让调用方拿到一份拷贝）才正确。这点与 clang-u01 的「返回局部变量地址」陷阱一致，只是对象换成了结构体。","c":{"lang":"c","code":"struct P* bad(void) { struct P p = {1,2}; return &p; }  // 悬垂指针，栈帧已失效"}},{"h":"四、柔性数组成员（Flexible Array Member）","s":"C99 允许结构体最后一个成员是未知长度的数组：","c":{"lang":"c","code":"struct Packet {\n    uint32_t len;\n    uint8_t  payload[];   // 柔性数组成员，不计入 sizeof\n};"}},{"h":"五、可运行示例：值返回 vs 指针返回","s":"","c":{"lang":"c","code":"#include <stdio.h>\n\nstruct Point { int x, y; };\n\nstruct Point make(void) {        // 值返回：调用方拿到独立副本\n    struct Point p = {3, 4};\n    return p;                    // 不是返回地址，无悬垂问题\n}\n\n…"}}]},{"id":"clang-u03/04-layout-practical-recipes","file":"04-layout-practical-recipes.md","title":"凯喵实战手记 · 内存布局、位域与 FFI：结构体里那些看不见的字节","kind":"flow","secs":[{"h":"现场 1：结构体大小不等于成员大小之和","s":"char 加 int 看着五字节，实际因为 int 要四字节对齐，char 后面塞了三字节填充，总共八字节。凯喵：算结构体大小时永远用 sizeof，不要靠手加；跨平台时对齐规则还可能不同，靠猜必然出错。","c":{"lang":"c","code":"struct S { char a; int b; };\nprintf(\"%zu\\n\", sizeof(struct S));  // 通常是 8，不是 5"}},{"h":"现场 2：成员顺序影响结构体大小","s":"同样的成员，按「从大到小」排能减少填充。凯喵：设计结构体时把大对齐的成员放前面，小成员往后排，能省下可观的 padding；数据量大时，这个细节能省下真金白银的内存。","c":{"lang":"c","code":"struct A { char a; int b; char c; };  // 12 字节\nstruct B { int b; char a; char c; };  // 8 字节"}},{"h":"现场 3：对齐是硬件的要求，不是编译器的怪癖","s":"很多 CPU 访问未对齐地址会变慢，某些架构（如 ARM 严格模式）直接触发异常。凯喵：对齐不是可有可无的优化，而是硬件契约。理解「每个类型有自己的对齐要求，结构体的对齐取成员最大值」，你才能解释为什么 sizeof 和你想的不一样。","c":null},{"h":"现场 4：#pragma pack 能压紧，但有代价","s":"强制一字节对齐可以取消填充，方便对接外部二进制协议，但会牺牲访问性能，在严格架构上还可能崩溃。凯喵：只在「对接固定格式的报文」时局部使用，用完立刻恢复默认对齐，绝不当成全局优化。","c":{"lang":"c","code":"#pragma pack(push, 1)\nstruct Packet { uint8_t type; uint32_t len; };\n#pragma pack(pop)"}},{"h":"现场 5：位域省空间，但布局是实现定义的","s":"struct { unsigned a : 3; unsigned b : 5; } 把字段压进同一个字节。凯喵：位域的具体排布（从低位还是高位开始、跨不跨字节）由编译器决定，跨平台传输时不能假设一致。要可移植的位操作，老老实实用移位与…","c":{"lang":"c","code":"struct Flags { unsigned ready : 1; unsigned mode : 3; };"}},{"h":"现场 6：位域不能取地址","s":"位域可能不落在字节边界上，所以不能对它取地址，也不能用 &。凯喵：需要指针或引用时，改用普通成员加掩码操作。这个限制经常在「想传位域地址给函数」时突然撞上。","c":null},{"h":"现场 7：联合体共享内存，写一个读另一个是未定义","s":"union { int i; float f; } 的所有成员共用同一块内存。凯喵：写 i 再读 f 是类型双关，标准上属于未定义行为（虽然很多编译器按位重解释）。要做合法的类型转换，用 memcpy 或 C++20 的 std::bi…","c":{"lang":"c","code":"union U { int i; float f; };\nu.i = 0x3f800000;\n// 读 u.f 在标准上是 UB，虽然常见实现得到 1.0f"}},{"h":"现场 8：联合体可以用来省内存","s":"互斥的字段用联合体共享空间，能显著减小结构体。凯喵：比如「要么是整数要么是字符串」的标签联合，用 union 加一个类型标记字段，就是经典的 tagged union。省内存的同时，别忘了自己维护类型标记的正确性。","c":null},{"h":"现场 9：memcpy 是安全的字节拷贝","s":"跨类型重解释内存时，memcpy 到同类型变量是标准认可的做法，编译器也会优化掉多余的拷贝。凯喵：需要「按位重解释」时优先 memcpy，比指针强转安全，也比联合体双关清晰。","c":{"lang":"c","code":"float f;\nuint32_t bits = 0x3f800000;\nmemcpy(&f, &bits, sizeof f);"}},{"h":"现场 10：FFI 边界的结构体布局必须显式约定","s":"和 C 库、其他语言交互时，结构体的字段顺序、对齐、大小必须完全一致，否则读出来的全是垃圾。凯喵：FFI 场景用固定宽度类型（int32_t 而非 int），显式 #pragma pack 或 repr(C)，并在两边各写一个 size…","c":{"lang":"c","code":"_Static_assert(sizeof(struct Packet) == 5, \"layout mismatch\");"}},{"h":"现场 11：字节序在跨机器传输时是隐形杀手","s":"小端机写、大端机读，整数直接错位。凯喵：网络传输统一用大端（网络字节序），用 htonl/ntohl 转换；或者干脆用文本/Protobuf 这类自带字节序约定的格式。","c":null},{"h":"现场 12：柔性数组成员要一次性分配","s":"struct { int len; uint8_t data[]; } 的 sizeof 不含 data，必须 malloc(sizeof p + n) 一次分配够。凯喵：不能放栈上、不能整体 memcpy（会漏掉柔性区）。这是 C 里…","c":{"lang":"c","code":"struct Buf { size_t len; char data[]; };\nstruct Buf *b = malloc(sizeof *b + n);"}},{"h":"现场 13：offsetof 是排查布局的利器","s":"offsetof(struct S, member) 给出成员相对结构体开头的偏移。凯喵：怀疑布局不对时，把每个成员的偏移打印出来，对齐填充一眼可见。这比盯着结构体定义猜要快得多。","c":{"lang":"c","code":"printf(\"%zu %zu\\n\", offsetof(struct S, a), offsetof(struct S, b));"}},{"h":"现场 14：跨平台布局要用固定宽度类型","s":"int 在不同平台可能是 2/4/8 字节，long 更是变化多端。凯喵：涉及序列化、FFI、文件格式的结构体，一律用 int32_t、uint64_t 这类固定宽度类型，别用「平台相关」的裸类型。","c":null},{"h":"凯喵叮嘱：先量布局，再谈优化","s":"最后叮嘱一句：怀疑结构体有问题时，第一件事是打印 sizeof 和每个成员的 offsetof，把真实布局画出来，而不是盯着定义脑补。凯喵见过太多「以为只占几字节、实际膨胀一倍」的事故，根子都是没量过。","c":null},{"h":"🧑‍💻 程序员视角","s":"struct { char a; int b; char c; } 在 64 位下是 12 字节而不是 6——编译器按最大成员对齐插入填充。把成员按「大到小」排列能压到 8 字节，这是零成本的优化。#pragma pack(1) 能压紧…","c":null},{"h":"🎓 博士生视角","s":"对齐规则可归纳为「每个成员的偏移是其对齐数的倍数，结构体总大小是最大对齐数的倍数」，其物理根源是「CPU 按字长批量读取，跨字边界访问需要两次读并拼接」。位域的实现（大端/小端下的位序、是否可跨存储单元）由 ABI 规定而非 C 标准…","c":null},{"h":"📚 考研者视角","s":"C 语言笔试高频：","c":null}]}],"exams":[{"kind":"choice","q":"结构体对齐与 sizeof","stem":"在 LP64（x86-64）平台上，struct { char c; int i; }; 的 sizeof 最可能是多少？已知 char 对齐 1、int 对齐 4，结构体整体对齐为 4。","opts":[{"k":"A","t":"5"},{"k":"B","t":"8"},{"k":"C","t":"6"},{"k":"D","t":"9"}],"ans":"B","why":"char c 占 0（1 字节），其后需填充到 4 边界，int i 从 4 开始占 4 字节到 8；末尾圆整到对齐 4 的倍数，sizeof=8。未对齐时不是 5。"},{"kind":"output","q":"重排结构体后的 sizeof","stem":"给出下面两个结构体（假设 int 4 字节、short 2 字节、char 1 字节，对齐同其大小）： c struct A { char c1; int i; char c2; short s; }; struct B { int i; short s; char c1; char c2; }; 请写出 sizeof(struct A) 与 sizeof(struct B)。","opts":[],"ans":"A=12 B=8","why":"A：c1(0) 填到4、i(4-7)、c2(8) 填到10、s(10-11) → 12。B：i(0-3)、s(4-5)、c1(6)、c2(7) 末尾圆整到4倍数 → 8。重排把小成员聚到尾部，省下 4 字节。"},{"kind":"coding","q":"用 container_of 思想从成员反推宿主结构","stem":"给定 struct List { struct List next; int val; };，以及一个指向 val 成员的指针 int pval，请写一段代码（用 offsetof）反推出宿主 struct List 指针。要求不使用任何库函数的遍历，仅用地址运算。","opts":[],"ans":"#include <stddef.h> struct List { struct List next; int val; }; / 已知 int pval 指向某节点的 val 成员 / struct List node = (struct List )((char )pval - offsetof(struct Li…","why":"container_of 的核心：成员地址减去该成员在结构体中的偏移，即宿主首地址。这是 Linux 内核侵入式链表的基础。注意结果只在 pval 确实指向 List.val 时有效，否则 UB。"},{"kind":"fix_error","q":"修复浅拷贝导致的双重释放","stem":"下面代码在 free(a.p) 与 free(b.p) 时会发生 double free。结构体含指针成员，赋值只是浅拷贝。请修复（保持两个对象各自拥有独立内存）： c struct Buf { char p; size_t n; }; int main(void) { struct Buf a; a.p = malloc(4); strcpy(a.p, \"hi\"); a.n = 4; struc…","opts":[],"ans":"struct Buf { char p; size_t n; }; struct Buf deep_copy(const struct Buf o) { struct Buf b; b.p = malloc(o->n); memcpy(b.p, o->p, o->n); b.n = o->n; return b; /…","why":"含指针的结构体赋值是逐成员浅拷贝，b.p 与 a.p 指向同一处，两次 free 即 double free。必须显式深拷贝（重新 malloc 并 memcpy 内容），让两个对象各自拥有独立内存。"},{"kind":"choice","q":"位域的可移植性","stem":"关于位域（bit-field），下列哪项是正确的？","opts":[{"k":"A","t":"位域从字的哪一端开始由 C 标准统一规定"},{"k":"B","t":"位域成员可以取地址（&field 合法）"},{"k":"C","t":"位域的比特排布是实现定义的，不宜用于跨平台二进制协议"},{"k":"D","t":"位域成员必须是整数类型，但符号性由标准统一规定为无符号"}],"ans":"C","why":"位域的起始端、跨字行为、符号性都是实现定义的，A/D 错；位域没有独立地址，&field 非法，B 错。用于跨平台协议应改用位移+掩码。"},{"kind":"explain","q":"union 读非活跃成员为什么是 UB？可移植的类型双关怎么做？","stem":"解释：为什么写入 union 一个成员后读取另一个成员在严格语义下是未定义行为？在需要「查看一个对象的比特表示」时，什么是可移植的做法？","opts":[],"ans":"可移植做法：用 memcpy 或 unsigned char 数组观察。 float f = 1.0f; uint32_t bits; memcpy(&bits, &f, sizeof bits); / 此时 bits 是 f 的比特表示，任何平台结果一致 /","why":"union 同一时刻只有一个活跃成员，读非活跃成员违反活性规则，且严格 aliasing 假设类型不混用，编译器可据此做激进优化。C11 §6.2.6.1 允许通过 unsigned char 观察任何对象的比特，因此 memcpy / char 数组才是可移植的类型重解释。"},{"kind":"coding","q":"合并两个有序数组（原地，用指针操作）","stem":"给定两个升序整数数组 nums1（容量 m+n，前 m 个有效）和 nums2（长度 n），把它们合并到 nums1 中并保持升序，要求原地（只用 O(1) 额外空间）。详见 external_url，不在此复述题面。","opts":[],"ans":"void merge(int nums1, int nums1Size, int m, int nums2, int nums2Size, int n) { int i = m - 1, j = n - 1, k = m + n - 1; while (i >= 0 && j >= 0) nums1[k--] = (n…","why":"从尾部向前填，避免覆盖 nums1 中尚未处理的有效元素；用三指针（i/j 指向两源末，k 指向目标末）原地归并。"}],"works":[{"h":"忘记对齐导致 sizeof 远超字段之和","d":"struct { char c; int i; }; 在小端 LP64 下是 8 字节（char 后填 3 字节），不是 5。把 char 夹在两个大成员之间更糟。正确写法：按对齐从大到小排（大成员在前、小成员聚尾），必要时用 _Static_assert(sizeof(S)==N, ...) 固化布局。"},{"h":"用位域写可移植二进制协议","d":"位域从字的哪端开始、是否跨字、无名位域对齐都是实现定义的；同一份代码在 GCC/Clang、大端/小端机器上比特排布可能完全不同。正确写法：协议字段一律用「位移 + 掩码」显式编码，如 (raw >> 3) & 0xF，并把字段宽/偏移写成常量。"},{"h":"用 union 读非活跃成员当类型双关（UB）","d":"写入 u.i 又读 u.f 在严格 aliasing 下是未定义行为，编译器可能返回「不是内存里那个比特」的值。正确写法：用 memcpy(&dst, &src, sizeof) 或 unsigned char 逐字节观察（C11 §6.2.6.1），可移植且避开活性成员限制。"},{"h":"结构体浅拷贝分裂指针所有权","d":"struct Buf b = a; 让 b.p == a.p，两者共享同一块堆内存，free 两次即 double free。正确写法：含指针的结构体要么显式深拷贝、要么明确「谁分配谁释放」的所有权、要么禁止拷贝。"},{"h":"返回局部结构体指针","d":"struct P f(){ struct P p=...; return &p; } 返回栈帧已失效的地址，得到悬垂指针。正确写法：返回结构体值（return p; 调用方拿到副本），需要逃逸生命周期再用 malloc 并约定释放责任。"},{"h":"以为传结构体一定「慢」而滥用 malloc","d":"小/中等结构体按 ABI 常走寄存器或隐藏指针返回，编译器已做拷贝消除；强行 malloc 反而引入堆分配与 free 成本。正确写法：先值传递/值返回，profile 显示瓶颈后再考虑动态分配。"},{"h":"误用柔性数组成员","d":"struct P { int len; uint8_t data[]; }; 的 sizeof 不含 data，且必须用 malloc(sizeof p + n) 分配；不能用于栈/静态对象，不能 memcpy 整个结构体（漏掉柔性区）。正确写法：动态分配时一次性包含负载，复制用按长度 memmove。"},{"h":"把 #pragma pack 当默认优化","d":"强制紧凑布局会取消对齐，在 ARM/RISC-V 等严格架构上引发 SIGBUS，且降低访问性能。正确写法：仅在对接外部固定二进制格式时局部使用，并尽快恢复默认对齐。"}],"asks":[{"q":"结构体内存对齐为什么会影响性能，甚至导致程序崩溃？","a":"对齐是「CPU 内存访问粒度」对数据布局的倒逼： 1. 性能：未对齐的对象可能需要多次内存事务才能拼出完整值（例如跨两个缓存行的 int），在 x86 上也有明显开销；对齐后一次取数即可。 2. 正确性（崩溃）：ARM、RISC-V、老 MIPS 等架构禁止未对齐访问，遇到未对齐的 int/double 加载会直接触发总线错误（SIGBUS）。x86 虽允许但代价更高。 3. 原子性：未对齐的读写…","fu":["为什么 x86 允许未对齐访问而 ARM 不允许？","#pragma pack(1) 会带来哪些隐患？什么场景必须用？"],"tag":"通用/字节"},{"q":"union 读非最后写入的成员为什么是未定义行为？类型双关怎么做才安全？","a":"活性成员规则：C 规定 union 同一时刻只有一个成员是「活跃的」，读取非最后写入的成员违反该规则，是 UB。更深层原因是严格别名规则（strict aliasing）：编译器假设不同类型不会别名同一段内存，可据此重排/缓存，于是它可能返回「不是内存里那个比特」的值。 安全做法： 1. C11 §6.2.6.1 允许通过 unsigned char 数组逐字节观察任何对象的比特表示。 2. 因此…","fu":["为什么 memcpy 能避开 aliasing 问题？","tagged union 相比裸 union 多付出什么代价？"],"tag":"通用/系统向"},{"q":"结构体传参和返回时，编译器做了什么「隐藏优化」？为什么不应盲目用 malloc 返回指针？","a":"结构体是值类型，但 ABI 决定实际传递方式： 1. 传参：小结构体常直接走寄存器；稍大的按 ABI 可能隐式改传「隐藏指针」（f(struct S s) 等价），调用方在栈上留副本、被调方经指针访问——调用者无感。 2. 返回：struct S g(void) 常改写为「调用方预留空间 + 传隐藏指针让被调方写入」，且 S x = g(); 可被优化成直接构造到目标，避免中间拷贝（RVO 类比）…","fu":["返回局部结构体指针为什么是悬垂？","RVO 在 C 里和 C++ 里的保证有何不同？"],"tag":"通用/编译器向"}]},{"id":"clang-u04","subj":"clang","title":"文件 IO 与二进制","summary":"","concepts":[{"id":"clang-u04/01-file-handle-and-buffer","file":"01-file-handle-and-buffer.md","title":"01 · FILE 句柄、缓冲与文件描述符","kind":"compare","secs":[{"h":"一、理论根基：标准库 IO 是一层「缓冲封装」","s":"C 的 <stdio.h> 不直接和系统打交道，而是在系统调用之上套了一层用户态缓冲。FILE 结构体（标准未规定内部，但各实现类似）里至少装着：","c":null},{"h":"二、实现机制：缓冲的三种模式与刷新时机","s":"setvbuf 可设置缓冲策略，标准定义了三类：","c":null},{"h":"三、用户态缓冲 vs 内核缓冲：数据安全的真正边界","s":"即使 fflush 成功，数据也只到了内核的页缓存（page cache），还没真正写到磁盘。要强制落盘还需：","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例：看出缓冲的存在","s":"","c":{"lang":"c","code":"#include <stdio.h>\n#include <unistd.h>\n\nint main(void) {\n    /* 行缓冲（终端）下遇 \\n 才刷；这里演示 fclose 前的累积 */\n    fprintf(stdout, \"hello \");\n    fprintf(stdout, \"world\");      /* 此时可能还在缓冲区 */\n    fflush(stdout);                /* 主动刷出，确保可见 */\n    fprintf(stdout, \"\\n\");\n…"}}]},{"id":"clang-u04/02-text-vs-binary-and-modes","file":"02-text-vs-binary-and-modes.md","title":"02 · fopen 模式、文本/二进制与随机访问","kind":"compare","secs":[{"h":"一、fopen 模式：一张表背下来","s":"加 b 变二进制：rb/wb/ab/r+b…。关键区别只在「文本流」会做换行转换与可能的 EOF 处理；二进制流逐字节保真。","c":null},{"h":"二、博士视角：文本 vs 二进制的换行陷阱","s":"C 标准允许文本流在 \\n 与宿主行结束符之间转换。在 Windows 上，行结束符是 CRLF（\\r\\n）：","c":null},{"h":"三、fseek / ftell：随机访问与定位","s":"","c":{"lang":"c","code":"fseek(fp, offset, whence);   /* whence: SEEK_SET 绝对 / SEEK_CUR 相对当前 / SEEK_END 文件尾 */\nlong pos = ftell(fp);        /* 当前位置（字节）；文本模式下返回值「未指定可移植含义」） */\nrewind(fp);                  /* = fseek(fp,0,SEEK_SET) + clearerr */"}},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例：二进制模式保留字节","s":"","c":{"lang":"c","code":"#include <stdio.h>\nint main(void) {\n    FILE *w = fopen(\"nl.txt\", \"w\");   /* 文本模式写 */\n    fputs(\"AB\\nCD\", w);               /* \\n 被翻译成 \\r\\n 落盘 */\n    fclose(w);\n    FILE *rb = fopen(\"nl.txt\", \"rb\"); /* 二进制读：原样 6 字节 */\n    unsigned char b[16]; size_t nb = fread(b, 1, 16, rb); fclose(rb);\n    printf(\"binary read: %zu bytes\\n\", nb);\n    return 0;\n…"}}]},{"id":"clang-u04/03-error-handling-and-eof","file":"03-error-handling-and-eof.md","title":"03 · 错误处理、返回值检查与 feof 语义","kind":"flow","secs":[{"h":"一、理论根基：IO 是「会失败的操作」，必须检查每一步","s":"文件 IO 几乎每一步都可能失败：文件不存在、权限不足、磁盘满、被信号打断、介质损坏。fopen 失败返回 NULL；fread/fwrite/fseek 等通过返回值和状态位报告失败。把 IO 当「必然成功」来写，是生产事故的温床。","c":null},{"h":"二、实现机制：fread/fwrite 的返回值与「短读」","s":"size_t fread(void ptr, size_t size, size_t nmemb, FILE ); 返回成功读到的「元素个数」（不是字节数，除非 size==1）。这与直觉不同：","c":{"lang":"c","code":"size_t got = fread(buf, 1, N, fp);\nif (got < N) {\n    if (ferror(fp)) { /* 真出错 */ }\n    else { /* 正常到 EOF，只读到 got 字节 */ }\n}"}},{"h":"三、errno / perror / strerror：错误原因的载体","s":"fopen 返回 NULL 时，具体原因存放在线程局部的 errno 里（#include <errno.h>）：","c":null},{"h":"四、feof 的语义：它是「事后结论」，不是「循环条件」","s":"这是最高频的 IO 错误。feof(fp) 只有在「一次读操作已经越过文件尾」之后才置位。因此：","c":{"lang":"c","code":"while (!feof(fp)) {           /* 错误！最后一次读到 EOF 后，循环仍会再进一次 */\n    fread(&x, ..., fp);        /* 这次读失败，x 是上一次的值或垃圾，却仍被使用 */\n}"}},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：feof 只在越过文件尾后为真","s":"","c":{"lang":"c","code":"#include <stdio.h>\nint main(void) {\n    FILE *w = fopen(\"e.txt\", \"w\");\n    fputs(\"AB\\n\", w);\n    fclose(w);\n    FILE *r = fopen(\"e.txt\", \"r\");\n    int c; int count = 0;\n    while ((c = fgetc(r)) != EOF) { count++; }   /* 以读失败为结束 */\n    printf(\"chars read=%d feof=%d\\n\", count, feof(r) ? 1 : 0);\n…"}}]},{"id":"clang-u04/04-fileio-practical-recipes","file":"04-fileio-practical-recipes.md","title":"C 文件 IO 实战手记：凯喵的十二次「写进去了但读不出来」","kind":"flow","secs":[{"h":"开场：FILE 是 fd 之上的缓冲层","s":"fopen 返回的 FILE 不是文件本身，而是一个结构体：里面有文件描述符（fd）、一块用户态缓冲区、当前位置、错误标志、EOF 标志。","c":{"lang":"c","code":"FILE* fp = fopen(\"a.txt\", \"w\");\nfprintf(fp, \"hello\");\n// 忘了 fclose"}},{"h":"收尾：文件 IO 的三条纪律","s":"凯喵最后总结：文件 IO 看起来 API 很多，但纪律只有三条。","c":null}]}],"exams":[{"kind":"choice","q":"fopen 模式的截断行为","stem":"用 fopen(\"data.txt\", \"w\") 打开一个已存在且非空的文件，会发生什么？","opts":[{"k":"A","t":"在原内容末尾追加"},{"k":"B","t":"文件被立即截断为 0 字节"},{"k":"C","t":"打开失败返回 NULL"},{"k":"D","t":"保留原内容，覆盖式写入"}],"ans":"B","why":"w 模式语义是「写 + 若存在则截断为 0」。要保留内容并覆盖应从头写用 r+，要在末尾追加用 a。想「存在则报错」需 POSIX 的 O_EXCL。"},{"kind":"output","q":"二进制文件大小","stem":"下面程序向二进制文件写入 7 个 int（每个 4 字节），然后用 fseek(SEEK_END)+ftell 求大小。设 int 为 4 字节、long 足够大，写出程序打印的内容： c FILE w=fopen(\"s.bin\",\"wb\"); int x=1; for(int i=0;i<7;i++) fwrite(&x,sizeof(int),1,w); fclose(w); FILE r=f…","opts":[],"ans":"size=28","why":"7 个 int × 4 字节 = 28 字节。二进制流下 ftell 返回可靠字节位置；若在文本流下该值不可移植。"},{"kind":"fix_error","q":"修复 feof 误用导致的多读一次","stem":"下面循环会多处理一次垃圾数据（把 EOF 当数据）。请改为以读操作的返回值为终止条件： c FILE f = fopen(\"in.txt\", \"r\"); int x; while (!feof(f)) { / 错误：feof 在越界读之后才为真 / fscanf(f, \"%d\", &x); printf(\"%d \", x); } fclose(f);","opts":[],"ans":"FILE f = fopen(\"in.txt\", \"r\"); if (!f) { perror(\"fopen\"); return 1; } int x; while (fscanf(f, \"%d\", &x) == 1) { / 以读成功为条件 / printf(\"%d \", x); } if (ferror(f)) {…","why":"feof 是事后状态，不能作为前置条件。fscanf 返回成功转换的个数，==1 表示本次确实读到一个整数；读到 EOF 或出错时循环自然退出，退出后再用 ferror 区分异常。"},{"kind":"coding","q":"写一个健壮的文件复制函数","stem":"实现 int copy_file(const char src, const char dst)，用块读写（fread/fwrite，size 传 1）复制任意二进制文件，并：① 两个 fopen 都必须判 NULL 并用 perror 报因；② 依据 fread 返回值累加已复制字节，正确处理短读；③ 失败时清理已打开/已创建的文件并返回非 0。","opts":[],"ans":"#include <stdio.h> int copy_file(const char src, const char dst) { FILE s = fopen(src, \"rb\"); if (!s) { perror(src); return 1; } FILE d = fopen(dst, \"wb\"); if (…","why":"核心是「以 fread 返回值为准」「size=1 让返回值即字节数」「fwrite 也要检查」「任何失败路径都 fclose 避免泄漏」。这正是 ex04 的健壮版。"},{"kind":"choice","q":"文本 vs 二进制模式（Windows 换行陷阱）","stem":"在 Windows 上，用文本模式 fopen(f,\"w\") 写入字节序列 AB 0A CD（即字符串 \"AB\\nCD\"），再用二进制模式 \"rb\" 读回，会得到多少字节？","opts":[{"k":"A","t":"5 字节（0A 不变）"},{"k":"B","t":"6 字节（0A 被扩展为 0D 0A）"},{"k":"C","t":"4 字节（换行被吞掉）"},{"k":"D","t":"取决于编译器，标准未规定"}],"ans":"B","why":"文本模式写会把 \\n(0A) 翻译成 \\r\\n(0D 0A) 落盘，于是磁盘上 6 字节；二进制读原样读出 6 字节。这正是「二进制数据误用文本模式会损坏」的根因。"},{"kind":"explain","q":"fflush 之后数据就安全落盘了吗？","stem":"解释：进程调用 fflush(fp) 成功后，数据是否一定已经在磁盘上？要真正持久化还需要什么？","opts":[],"ans":"/ 仅 flush 到内核还不够 / fflush(fp); / 还需把内核页缓存刷到磁盘（POSIX） / fsync(fileno(fp)); / 取底层 fd 再 fsync /","why":"IO 栈分多层：fwrite 进用户态缓冲 → fflush 刷到内核页缓存 → fsync 才真正写盘。fflush 成功只表示数据离开进程的用户缓冲，断电时内核缓存仍可能丢失。需要持久性（如数据库日志）必须一路 fsync（或 fdatasync）。"},{"kind":"coding","q":"LeetCode 1480 · 一维数组的动态和（用文件 IO 读入写出）","stem":"给定数组，输出其「动态和」（running sum）。要求从文件 in.txt 读入整数序列、把结果写到 out.txt（每行一个）。详见 external_url，不在此复述题面。","opts":[],"ans":"/ 读 in.txt，算 running sum，写 out.txt / #include <stdio.h> int main(void){ FILE in=fopen(\"in.txt\",\"r\"); if(!in){perror(\"in\");return 1;} FILE out=fopen(\"out.txt\",\"w…","why":"running sum 即前缀和：读一个数累加一个并写出。本题重点是「IO 必判 NULL + 正确循环条件」，运算本身 O(n)。"}],"works":[{"h":"二进制数据用文本模式读写导致损坏","d":"在 Windows 上，文本模式会把 \\n 与 \\r\\n 互转，0A 被偷偷扩成 0D 0A，图片/结构体/压缩包直接坏掉。正确写法：任何非文本字节一律用 \"b\" 模式（rb/wb），且读写两端模式一致。"},{"h":"fopen 不判 NULL 就解引用","d":"文件不存在/无权限时 fopen 返回 NULL，紧接着 fread(fp,...) 是段错误。正确写法：每次 fopen 后 if (!fp) { perror(...); return ...; }。"},{"h":"把 w/w+ 当「存在则报错」用","d":"w 会直接截断已有文件到 0 字节，重要内容瞬间消失。正确写法：想「不存在才创建、存在则报错」用 POSIX open(path, O_CREAT|O_EXCL, 0600)，或先 fopen \"r\" 探测存在性。"},{"h":"用 feof 当循环条件导致多读一次","d":"feof 只在「读操作已越过文件尾」后才置位，用它当 while(!feof) 前置条件必然多进一次循环、把 EOF(-1) 当数据使用。正确写法：以 fread/fgetc/fscanf 的返回值/EOF 为终止条件，结束后才用 feof/ferror 区分原因。"},{"h":"忽略 fread/fwrite 的返回值","d":"返回的是「元素个数」而非成功标志；磁盘满或到 EOF 时返回少于请求值。把 fwrite(..., fp) 当无返回值调用会吞掉短写。正确写法：size 传 1、nmemb 传字节数，比较返回值与实际长度，区分 feof/ferror。"},{"h":"程序退出前没 fclose/fflush 丢失数据","d":"全缓冲文件（普通文件默认）的数据停在用户态缓冲，return 0/exit() 才会替你 flush；abort()/kill -9 不会。正确写法：写完关键数据主动 fflush(fp)，必要时 fsync(fileno(fp))；长进程别依赖退出时才刷。"},{"h":"读写切换的流漏掉 fseek/fflush","d":"同一 FILE 上「写后读」或「读后写」之间必须插入定位或刷新，否则行为未定义（缓冲与位置不一致）。正确写法：每次读写角色切换前 fseek(fp,0,SEEK_CUR) 或 fflush+定位。"},{"h":"混用 FILE 与底层 read/write 同一 fd","d":"stdio 的用户态缓冲会截留数据，两套 API 看到的位置/内容不一致，结果是 UB。正确写法：要么全程用 stdio，要么全程用 read/write，需要底层访问时用 fileno(fp) 并在切换前后 fflush。"}],"asks":[{"q":"缓冲 IO（stdio）与直接 IO（read/write）各有什么取舍？什么时候该绕过 FILE？","a":"缓冲 IO（FILE）：在底层 fd 之上加用户态缓冲，把多次小操作聚成少量系统调用，减少上下文切换、显著提升吞吐；还提供格式化（fprintf）、行读取（fgets）等便捷接口。代价是多了「缓冲状态」需要管理（flush/seek 约束），且与底层 fd 混用是 UB。 直接 IO（read/write）：每次直接进内核，无用户态缓冲，可控性最高、语义最干净，适合：需要 O_DIRECT 绕过页…","fu":["setvbuf 的三种模式分别在什么场景用？","为什么 read 可能返回「短读」（short read）？"],"tag":"通用/系统向"},{"q":"fwrite 返回成功了，数据就一定写到磁盘上了吗？要真正持久化怎么做？","a":"不是。 IO 栈分层： 1. fwrite 成功 = 数据进了 FILE 的用户态缓冲； 2. fflush(fp) 成功 = 数据经 write() 进入内核页缓存（page cache）； 3. fsync(fd) / fdatasync(fd) = 内核把页缓存真正刷到磁盘介质。 进程被 kill -9 或崩溃时，连内核页缓存都可能未落盘。abort() 同样不会 flush 用户缓冲。所以…","fu":["fsync 和 fdatasync 有什么区别？","O_DIRECT 和 fsync 各自解决什么问题？"],"tag":"通用/数据库向"},{"q":"为什么 feof 不能作为循环条件？正确读取到文件尾的写法是什么？","a":"feof(fp) 反映「是否已经发生过一次越过文件尾的读操作」，它只在读操作失败（越界）之后才置位，而不是「接下来还有没有数据」的预告。所以 while(!feof(fp)) 会在最后一次成功读完后再进一次循环，把 EOF(-1)/垃圾当数据使用——典型的多读一次 bug。 正确写法：以读操作本身的返回值或 EOF 为终止条件： - while ((c = fgetc(fp)) != EOF) -…","fu":["feof 和 ferror 的状态什么时候需要 clearerr 清除？","读后写/写后读同一流为什么必须 fseek？"],"tag":"通用/字节"}]},{"id":"clang-u05","subj":"clang","title":"预处理与宏","summary":"","concepts":[{"id":"clang-u05/01-translation-phases","file":"01-translation-phases.md","title":"01 · 翻译阶段与 #include 的文本包含语义","kind":"flow","secs":[{"h":"一、理论根基：C 程序如何变成可执行文件","s":"从一份 .c 源文件到可运行程序，要经过翻译（translation）与链接两大阶段。C 标准（C11 §5.1.1.2）把「翻译」细分为 7 个严格有序的阶段（phase），理解这个顺序，是理解「为什么某些写法合法、某些未定义」的钥匙…","c":{"lang":"text","code":"源文件(.c/.h)\n   │  phase 1  三字符序列/换行规范、源/执行字符集识别\n   ▼\n   │  phase 2  反斜杠换行 \\ 拼接物理行 → 逻辑行\n   ▼\n   │  phase 3  分解为 注释/空白/预处理 token（标识符、数字、标点、字符串等）\n   ▼\n   │  phase 4  ★ 预处理：执行 #include/#define/#if 等指令\n   │           - #include 把目标文件整体「文本替换」进来（可递归）\n…"}},{"h":"二、实现机制：#include 到底是什么","s":"#include <stdio.h> 与 #include \"mymath.h\" 的语义是纯文本包含：","c":{"lang":"c","code":"/* main.c */\n#include \"mymath.h\"      /* 内容被整段贴进来 */\nint main(void) { return my_add(1,2); }"}},{"h":"三、工程实践：翻译单元与「一次定义规则」","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例","s":"见 examples/ex07.json（头文件守卫演示）与 examples/ex10.json（gcc -E 展开全过程）。前者展示「同一头文件被包含三次却只生效一次」，后者直接把预处理器的输出贴给你看。","c":null}]},{"id":"clang-u05/02-macro-hygiene","file":"02-macro-hygiene.md","title":"02 · 对象宏、函数宏与宏的「卫生」问题","kind":"flow","secs":[{"h":"一、理论根基：宏是「文本替换」而非「调用」","s":"#define 有两类：","c":{"lang":"c","code":"#define PI 3.14159                 /* 对象宏：一个标识符替换成一段 token */\n#define MAX(a, b) ((a) > (b) ? (a) : (b))   /* 函数宏：带形参的替换 */"}},{"h":"二、实现机制：两类典型「不卫生」陷阱","s":"函数宏的形参和整体结果都必须加括号，否则替换后会被外层表达式的运算符「吃掉」。","c":{"lang":"c","code":"#define SQUARE(x) x * x\nint r = SQUARE(2 + 1);   /* 展开为 2 + 1 * 2 + 1 = 5，而非 9 */"}},{"h":"三、工程实践：什么时候用宏、什么时候用 inline","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例","s":"见 examples/ex01.json（括号陷阱）、examples/ex02.json（多重求值）、examples/ex03.json（do-while(0)）。三个示例的真实输出直观展示了三类问题。","c":null}]},{"id":"clang-u05/03-macro-operators-conditional","file":"03-macro-operators-conditional.md","title":"03 · # 与 ## 运算符、条件编译","kind":"flow","secs":[{"h":"一、理论根基：预处理期的「元编程」运算符","s":"普通宏做 token 替换，而 # 和 ## 让你在替换过程中操作 token 本身，属于预处理期的元编程。","c":{"lang":"c","code":"#define STR(x)  #x\nSTR(Hello World)   →  \"Hello World\"\nSTR(a + b)        →  \"a + b\""}},{"h":"二、实现机制：条件编译如何工作","s":"条件编译指令让预处理器决定哪些代码进入翻译单元：","c":{"lang":"c","code":"#if 常量表达式        /* 表达式为真才保留下方代码 */\n#ifdef 宏名           /* 等价于 #if defined(宏名) */\n#ifndef 宏名          /* 等价于 #if !defined(宏名) */\n#elif / #else / #endif\n#define defined(宏)    /* 运算符：宏已定义则为真 */"}},{"h":"三、工程实践：用条件编译隔离差异","s":"要点：","c":{"lang":"c","code":"#if defined(_WIN32)\n    #include <windows.h>\n#elif defined(__linux__)\n    #include <unistd.h>\n#endif\n\n#define ENABLE_LOG 1\n#if ENABLE_LOG\n    #define LOG(...) fprintf(stderr, __VA_ARGS__)\n…"}},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例","s":"见 examples/ex04.json（# 字符串化与二次展开）、examples/ex05.json（## 拼接）、examples/ex06.json（#if/#ifdef/defined 组合的条件编译）。","c":null}]},{"id":"clang-u05/04-header-guards","file":"04-header-guards.md","title":"04 · 头文件守卫：#ifndef 守卫 vs #pragma once","kind":"compare","secs":[{"h":"一、问题根源：重复包含","s":"一个头文件常被多个 .c 间接包含（A 含 B，C 含 B）。若 B 里定义了 struct Foo 或内联函数，展开两次后同一翻译单元内出现两份相同定义，触发编译错误（redefinition），或在链接期出现 multiple de…","c":null},{"h":"二、实现机制：#ifndef 守卫","s":"最经典、完全可移植的写法：","c":{"lang":"c","code":"#ifndef MYMATH_H\n#define MYMATH_H\n/* 头文件真正的内容 */\nint my_add(int a, int b);\n#endif /* MYMATH_H */"}},{"h":"三、实现机制：#pragma once","s":"非标准但被几乎所有现代编译器（GCC/Clang/MSVC）支持的写法：","c":{"lang":"c","code":"#pragma once\n/* 头文件内容 */"}},{"h":"四、工程实践：到底用哪个","s":"","c":null},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例","s":"见 examples/ex07.json：把同一个头文件 mymath.h 的内容（带 #ifndef 守卫）在同一个翻译单元里写出两次以模拟重复包含，程序仍能编译通过并正确运行——守卫把第二次包含整体跳过了。","c":null}]},{"id":"clang-u05/05-advanced-macros","file":"05-advanced-macros.md","title":"05 · 进阶宏技巧：X-Macro、_Generic、_Static_assert","kind":"flow","secs":[{"h":"一、X-Macro：用「一张表」生成多份代码","s":"X-Macro 不是标准特性，而是一种惯用法：先定义一张「数据表」宏，再多次用不同的「展开器」宏把它展开成枚举、字符串表、函数表等，保证它们永远同步。","c":{"lang":"c","code":"/* 1) 单一数据源：改这里，其它自动跟着变 */\n#define COLOR_LIST(X)   \\\n    X(RED,   \"#ff0000\") \\\n    X(GREEN, \"#00ff00\") \\\n    X(BLUE,  \"#0000ff\")\n\n/* 2) 生成枚举 */\n#define X_ENUM(name, hex) COLOR_##name,\ntypedef enum { COLOR_LIST(X_ENUM) COLOR_COUNT } Color;\n…"}},{"h":"二、_Generic（C11）：基于表达式类型的「类型分发」","s":"C 没有函数重载，但 C11 的 _Generic 允许在编译期按表达式类型选择分支，从而模拟泛型：","c":{"lang":"c","code":"#define type_name(x) _Generic((x), \\\n    int: \"int\", double: \"double\", char*: \"char*\", default: \"other\")\n\ntype_name(3);        /* \"int\" */\ntype_name(3.14);     /* \"double\" */"}},{"h":"三、_Static_assert（C11）：编译期断言","s":"_Static_assert(常量表达式, \"失败信息\") 在编译期检查条件，失败直接阻断编译并打出诊断信息：","c":{"lang":"c","code":"#include <limits.h>\n_Static_assert(CHAR_BIT == 8, \"一个字节必须是 8 位\");\n_Static_assert(sizeof(int) == 4, \"int 必须是 4 字节\");"}},{"h":"四、工程实践与取舍","s":"","c":null},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例","s":"见 examples/ex08.json（X-Macro 生成颜色枚举与字符串表）、examples/ex09.json（_Static_assert 在编译期断言 int==4 字节、CHAR_BIT==8，全部通过）。","c":null}]},{"id":"clang-u05/06-macro-recipes","file":"06-macro-recipes.md","title":"clang-u05 · 预处理与宏实战：凯喵的宏卫生清单","kind":"flow","secs":[{"h":"宏只是文本替换，不是函数","s":"#define SQR(x) xx 调 SQR(a+1) 会展开成 a+1a+1，优先级全错。凯喵的规矩：宏参数和整体都加括号。","c":{"lang":"c","code":"#define SQR(x) ((x)*(x))     // 参数和整体都括起来\nint y = SQR(a+1);            // ((a+1)*(a+1))，正确"}},{"h":"宏卫生：括号与 do-while(0)","s":"多语句宏直接展开会破坏 if/else 配对。标准写法是用 do { ... } while(0)，让它成为一个语句块，既能加分号又能正确嵌进 if。","c":{"lang":"c","code":"#define SAFE_FREE(p) do { free(p); (p) = NULL; } while(0)\nif (cond) SAFE_FREE(ptr);    // 不会因为缺大括号而少执行\nelse { /* ... */ }"}},{"h":"条件编译的开关自检","s":"关键开关用 #ifdef / defined() 显式判断，避免宏名拼错静默走 else。配合 #pragma message 或 _Static_assert 在编译期暴露配置错误。","c":{"lang":"c","code":"#ifdef ENABLE_FOO\n    /* 开启路径 */\n#else\n    #pragma message(\"ENABLE_FOO not defined, using fallback\")\n#endif"}},{"h":"头文件守卫的两种写法","s":"传统 #ifndef X_H / #define X_H / #endif 防重复包含；现代用 #pragma once（编译器原生、更快、不受命名冲突影响）。两者等价，新项目优先 #pragma once。","c":null},{"h":"头文件守卫忘了会怎样","s":"同一头文件被包含两次，里面的类型/函数定义重复，链接期报「重定义」。凯喵强调：每个头文件第一行就写守卫，别等报错才补。","c":null},{"h":"宏名拼错的静默 else","s":"#if ENABLE_FOO 里 ENABLE_FOO 拼错会被当作 0，条件静默为假，逻辑悄悄改变且无任何报错。用 #ifdef 或 defined() 至少能区分「未定义」。","c":null},{"h":"多行宏与反斜杠续行","s":"多行宏每行末尾要加 \\ 续行（最后一行不用）。编辑器若把 \\ 后带了空格，续行就断，宏残缺。凯喵用 do-while(0) 块减少续行需求。","c":null},{"h":"用 _Static_assert 兜底常量","s":"编译期就能查的约束，用 _Static_assert（C11）写死，比运行时崩在客户机器强。","c":{"lang":"c","code":"_Static_assert(sizeof(int) == 4, \"int must be 4 bytes here\");"}},{"h":"现代 C++ 替代宏的清单","s":"C++ 里能不用宏就别用：constexpr/enum 代替常量宏，inline/template 代替函数宏，using 代替类型宏。宏只在「需要字符串化、条件编译、跨翻译单元代码生成」时保留——并且务必守卫生。","c":null},{"h":"🧑‍💻 程序员视角","s":"#define SQ(x) xx 在 SQ(a+1) 上展开成 a+1a+1——每个参数和整个表达式都要加括号：((x)(x))。多语句宏必须包 do { ... } while(0)，否则在 if (c) MACRO(); else…","c":null},{"h":"🎓 博士生视角","s":"预处理器在「词法分析之后、语法分析之前」运行，它不理解类型与作用域，只做记号替换与条件编译。这决定了宏的三个固有缺陷：无类型检查、参数可能多次求值（副作用）、调试信息缺失。do-while(0) 惯用法之所以成立，是因为它把多条语句包装…","c":null},{"h":"📚 考研者视角","s":"C 语言笔试高频：","c":null}]}],"exams":[{"kind":"choice","q":"关于宏替换发生的阶段，正确的是","stem":"选择正确描述「宏展开发生在程序构建流程哪一步」的选项。","opts":[{"k":"A","t":"宏在链接阶段才被替换"},{"k":"B","t":"宏在语法/语义分析之后、生成汇编之前被替换"},{"k":"C","t":"宏在预处理阶段（语法分析之前）被纯文本替换"},{"k":"D","t":"宏在运行期才展开"}],"ans":"C","why":"宏属于预处理指令，在翻译 phase 4 被展开，此时还没有语法/语义分析，因此是纯文本 token 替换，不做类型检查。"},{"kind":"fix_error","q":"修复带副作用宏的双重求值","stem":"下面宏用于求较大值，但 MAX(i++, 2) 会因多重求值得到错误结果。请修复（保留求最大值的语义、避免副作用）： c #define MAX(a, b) ((a) > (b) ? (a) : (b)) 提示：最稳妥的做法是改用 static inline 函数，使参数只求值一次。","opts":[],"ans":"static inline int max_i(int a, int b) { return a > b ? a : b; } / 调用前先把副作用算清：int t = i++; max_i(t, 2); /","why":"宏会把 i++ 替换进两个位置导致两次自增（比较一次、返回一次），结果依赖求值顺序且属未指定行为。改用 inline 函数只求值一次，且有类型检查、可调试。"},{"kind":"output","q":"读宏展开写输出","stem":"c #include <stdio.h> #define F(x) #x #define G(x) F(x) #define N 42 int main(void){ printf(\"%s\\n\", F(N)); printf(\"%s\\n\", G(N)); }","opts":[],"ans":"N 42","why":"F(N) 中 # 抑制参数展开，直接把 N 变成字符串 \"N\"；G(N) 经 F(x) 间接一层，参数先展开为 42 再字符串化，得到 \"42\"。"},{"kind":"coding","q":"写一个卫生的「调试日志」宏","stem":"实现一个 DEBUG_LOG(...) 宏：仅在定义了 DEBUG 宏时把信息打印到 stderr，否则编译为空语句；要求能像 printf 一样接收格式化参数，且作为单语句可安全放进 if/for。","opts":[],"ans":"#ifdef DEBUG #define DEBUG_LOG(...) fprintf(stderr, __VA_ARGS__) #else #define DEBUG_LOG(...) ((void)0) #endif","why":"用 #ifdef DEBUG 控制开关；非 DEBUG 下展开为 ((void)0)（void 类型的合法空语句，可出现在任何语句位置）；__VA_ARGS__ 接收可变参数。本例是单语句宏无需 do-while(0)，但含多条语句时仍需包裹。"},{"kind":"choice","q":"关于头文件守卫，错误的是","stem":"选择错误描述。","opts":[{"k":"A","t":"#ifndef 守卫靠宏名去重，宏名必须全局唯一"},{"k":"B","t":"#pragma once 靠文件身份去重，可能因宏名冲突而失效"},{"k":"C","t":"守卫解决「同一翻译单元内」的重复包含"},{"k":"D","t":"守卫无法解决跨翻译单元的全局符号冲突"}],"ans":"B","why":"恰好相反：#pragma once 按文件身份去重，所以没有宏名冲突风险；#ifndef 守卫才可能因为宏名重名而误判。二者都只解决单翻译单元内的重复包含，跨单元符号冲突要靠 static/extern。"},{"kind":"design","q":"LeetCode 136 · 只出现一次的数字","stem":"给定一个非空整数数组，除某个元素只出现一次外，其余每个元素均出现两次，找出那个只出现一次的元素。要求用 C 语言实现（详见 external_url，不在此复述题面；提示：可用异或性质，O(n) 时间、O(1) 空间）。","opts":[],"ans":"int singleNumber(int nums, int numsSize) { int r = 0; for (int i = 0; i < numsSize; i++) r ^= nums[i]; return r; }","why":"异或满足交换律与 x^x=0、x^0=x；成对元素异或抵消，剩下的就是只出现一次的数。这是 C 面试常见的位运算 + 数组题。"},{"kind":"design","q":"牛客 BM1 · 反转链表","stem":"给定一个单链表，将其反转并返回新的头节点。请用 C 语言实现（详见 external_url，不在此复述题面）。","opts":[],"ans":"struct ListNode reverseList(struct ListNode head) { struct ListNode p = NULL, c = head; while (c) { struct ListNode n = c->next; c->next = p; p = c; c = n; } re…","why":"三指针（prev/cur/next）原地反转；这是 C 指针与链表操作的经典题，呼应 clang-u01 的指针运算。"}],"works":[{"h":"宏参数不加括号，被外层运算符优先级「吃掉」","d":"#define SQUARE(x) x x 在 SQUARE(2 + 1) 中展开成 2 + 1 2 + 1 = 5。 参数与整体都加括号：#define SQUARE(x) ((x) (x))。"},{"h":"宏参数带副作用导致多重求值","d":"#define MAX(a,b) ((a)>(b)?(a):(b))，调用 MAX(i++, 2) 会让 i++ 被求值两次（比较一次、返回一次），结果依赖求值顺序且产生未指定行为。 先把值算进局部变量再传，或改用 static inline 函数；绝不给宏传自增/赋值等带副作用的实参。"},{"h":"多语句宏未用 do { } while (0) 包裹","d":"#define LOG(x) printf(\"A\\n\"); printf(\"B\\n\"); 放在 if (c) LOG(k); 中，只有第一条语句受 if 管辖，第二条恒执行。 一律写成 #define LOG(x) do { printf(\"A\\n\"); printf(\"B\\n\"); } while (0)。参见 examples/e…"},{"h":"头文件缺守卫导致重复定义","d":"头文件里放了 struct/inline 定义却没守卫，被多个 .c 间接包含后同一翻译单元出现两份定义 → 编译报 redefinition。 每个头文件加 #ifndef XXX_H / #define XXX_H / #endif（或 #pragma once）。参见 examples/ex07.json。"},{"h":"# 字符串化前没有「二次展开」层，拿到的是宏名而非值","d":"#define VERSION 2026 + STR(VERSION) 得到 \"VERSION\" 而非 \"2026\"，因为 # 会抑制参数展开。 用 TOSTR(x) STR(x) 间接一层，先让 VERSION 展开成 2026 再字符串化。参见 examples/ex04.json。"},{"h":"头文件里放「带存储的全局变量定义」引发 multiple definition","d":"在头文件写 int g = 0;，每个包含它的 .c 都会定义一份 g，链接期冲突。 头文件用 extern int g;，真正的定义只放在一个 .c 里。"},{"h":"_Generic 加了 default 后漏掉的类型不再报警","d":"default: ... 会吞掉所有未列出的类型分支，可能掩盖本该覆盖的类型。 仅当确实要兜底时才加 default；核心类型逐一显式列出。"},{"h":"条件编译里引用了拼错的宏名却静默走 else","d":"#if ENABLE_FOO 中 ENABLE_FOO 若拼写错误，会被当作 0，条件静默为假，逻辑悄悄改变且无任何报错。 关键开关用 #ifdef/defined() 显式判断，或配合 _Static_assert/#pragma message 自检。"}],"asks":[{"q":"宏替换发生在程序构建的哪个阶段？实际工程中宏和 inline 函数该怎么选？","a":"宏在预处理阶段（翻译 phase 4）被展开，早于语法/语义分析，属于纯文本 token 替换，不做类型检查、不求值参数。inline 函数是编译/链接期能力：有类型检查、参数只求值一次、可单步调试。 工程取舍：优先用 static inline 函数——除非需要 token 级元编程（字符串化 #、拼接 ##、基于 _Generic 的泛型、可变参数日志宏）才用宏。用宏时必须遵守三条卫生铁律：参…","fu":["为什么宏参数带自增会出错而 inline 不会？","可变参数宏 __VA_ARGS__ 在空参数时有什么坑（C99 的 ##__VA_ARGS__）？"],"tag":"通用/字节"},{"q":"# 与 ## 的运算顺序是什么？为什么 STR(VERSION) 得到的是宏名而不是它的值？","a":"C 标准规定宏展开顺序：① 先对宏体做参数替换；② 再处理 #（字符串化）与 ##（拼接）；③ 对得到的结果重新扫描一遍（此时可能再次展开新出现的宏）。 关键点是：# 会抑制其参数的进一步宏展开。所以 STR(VERSION) 中 VERSION 被直接变成字符串 \"VERSION\"，而不会先替换成 2026。要拿到值，需要间接一层：#define TOSTR(x) STR(x) 再由 TOSTR…","fu":["重新扫描阶段还可能展开出新的宏吗？举个 X-Macro 的例子","## 拼接出的新 token 如果恰好是宏名，会被继续展开吗？"],"tag":"通用/腾讯"},{"q":"头文件守卫 #ifndef 与 #pragma once 的区别与取舍？","a":"#ifndef 守卫是逻辑去重：靠一个唯一宏名判断，标准、100% 可移植，但有宏名冲突风险（重名会误跳过），且每次都要文本扫描。#pragma once 是物理去重：编译器按文件身份（路径/inode）判断，更简洁、略快、无宏名冲突，但它是事实标准而非 ISO C（不过 GCC/Clang/MSVC 全支持）。 重要边界：两者都只解决「同一翻译单元内」的重复包含；跨翻译单元的全局符号冲突（mul…","fu":["守卫能防止头文件里全局变量 multiple definition 吗（跨单元层面）？","为什么现代项目多数直接选 #pragma once？"],"tag":"通用"}]},{"id":"clang-u06","subj":"clang","title":"Makefile 与构建","summary":"","concepts":[{"id":"clang-u06/01-compilation-phases","file":"01-compilation-phases.md","title":"编译四阶段：从 .c 到可执行文件","kind":"flow","secs":[{"h":"一、四个阶段与它们的产物","s":"C 程序的构建并不是「一步编译」，而是 四个可独立观察的阶段。GCC 为每段都留了开关：","c":{"lang":"text","code":"main.c ──[预处理 -E]──> main.i ──[编译 -S]──> main.s ──[汇编 -c]──> main.o ─┐\n                                                                            ├─[链接]─> app\nutil.c ──[预处理 -E]──> util.i ──[编译 -S]──> util.s ──[汇编 -c]──> util.o ─┘"}},{"h":"二、目标文件里到底有什么","s":".o 不是「半个可执行文件」，它是一个有结构的容器：","c":null},{"h":"三、重定位：链接器存在的根本原因","s":"编译 util.c 时，编译器不可能知道 add 最终会被放在哪个地址——它取决于其他目标文件的大小。","c":null},{"h":"四、🧑‍💻 程序员视角","s":"很多人对着代码找半天语法，其实问题在编译命令里漏了一个 .o。","c":null},{"h":"五、🎓 博士生视角","s":"若没有分离编译，N 个源文件的工程每次构建都是 O(N) 次全量分析；分离后，一次增量构建的代价是 O(变更闭包)。","c":null},{"h":"六、📚 考研者视角","s":"必背对照表：","c":null}]},{"id":"clang-u06/02-makefile-mechanics","file":"02-makefile-mechanics.md","title":"Makefile 的机制：规则、依赖图与时间戳","kind":"flow","secs":[{"h":"一、一条规则的三要素","s":"Make 的执行模型可以概括为三步：","c":{"lang":"makefile","code":"target: prerequisites\n<TAB>recipe"}},{"h":"二、时间戳：Make 唯一的判据","s":"Make 不比较内容，只比较 mtime（修改时间）：","c":{"lang":"text","code":"需要重建  ⟺  target 不存在  ∨  ∃ prereq: mtime(target) < mtime(prereq)"}},{"h":"三、变量：= 与 := 的语义差异","s":"其他赋值：","c":{"lang":"makefile","code":"A = $(B)\nB = later\n\nC := $(D)\nD := later"}},{"h":"四、自动变量","s":"配合模式规则：","c":{"lang":"makefile","code":"%.o: %.c\n<TAB>$(CC) $(CFLAGS) -c $< -o $@"}},{"h":"五、.PHONY：为什么必须有","s":".PHONY 声明的目标「不是一个真实文件」，因此 make 永远执行它的 recipe，且不做 mtime 比较。","c":{"lang":"text","code":"$ touch clean          # 有人（或某次误操作）建了这个文件\n$ make clean\nmingw32-make: 'clean' is up to date.      # 什么都不做！"}},{"h":"六、🧑‍💻 程序员视角","s":"要点：","c":{"lang":"makefile","code":"CC      := gcc\nCFLAGS  := -std=c11 -O2 -Wall -Wextra\nTARGET  := app\nOBJS    := main.o util.o\n\n$(TARGET): $(OBJS)\n\t$(CC) $(CFLAGS) -o $@ $^\n\n%.o: %.c\n…"}},{"h":"七、🎓 博士生视角","s":"用文件系统（mtime）作为唯一的外置状态。这个设计极其优雅，也极其脆弱——因为它把「内容的正确性」","c":null},{"h":"八、📚 考研者视角","s":"必背对照表（Makefile 与 408 的映射）：","c":null}]},{"id":"clang-u06/03-incremental-deps-and-parallel","file":"03-incremental-deps-and-parallel.md","title":"增量构建的陷阱与并行构建","kind":"flow","secs":[{"h":"一、最普遍、最隐蔽的 bug：头文件依赖缺失","s":"看一份「看起来没问题」的 Makefile：","c":{"lang":"makefile","code":"util.o: util.c\n\t$(CC) -c util.c -o util.o"}},{"h":"二、make -j：并行构建与竞态","s":"make -j8 让 make 同时跑 8 个 recipe。它依据依赖图做拓扑排序，","c":{"lang":"text","code":"线程 A：编译 util.c  ->  读到 util.h 的旧内容\n线程 B：生成 util.h（比如头文件也是由某个规则生成的）"}},{"h":"三、递归 make 的问题","s":"大型工程常写成：","c":{"lang":"makefile","code":"subsystem:\n\t$(MAKE) -C src/subsystem"}},{"h":"四、构建系统的演进：为什么大家不再手写 Makefile","s":"但 Makefile 不会消失——它是理解这一切的地基，而且嵌入式/Linux 内核仍以 Make/Kbuild 为主。","c":null},{"h":"五、🧑‍💻 程序员视角","s":"make -n（dry run）与 make -p（打印数据库）是两个被严重低估的调试利器：","c":{"lang":"text","code":"1. make clean && make            # 最粗暴也最有效：排除增量构建问题\n2. 若 clean 后正常 -> 是依赖缺失，去查头文件依赖（-MMD -MP 有没有加）\n3. 若 clean 后仍不对 -> 问题在代码/编译选项，看 -O 级别与宏定义\n4. make -n                       # 只看要执行什么命令，不执行\n5. make -p | grep '^util.o'      # 打印 make 内部数据库，看它认为 util.o 依赖什么"}},{"h":"六、🎓 博士生视角","s":"形式化地，设真实依赖图为 $G^$，Makefile 声明的图为 $G$。若 $G \\subsetneq G^$，","c":null},{"h":"七、📚 考研者视角","s":"必背对照表：","c":null}]},{"id":"clang-u06/04-debugging-make-and-modern-builds","file":"04-debugging-make-and-modern-builds.md","title":"clang-u06 · 调试 Make 与构建系统演进","kind":"flow","secs":[{"h":"用 make -n / --dry-run 预览命令","s":"不改任何东西，只打印将要执行的 recipe。改了变量或规则后，先 -n 看一眼是不是你想跑的那条命令，再真跑。","c":{"lang":"make","code":"make -n all            # 打印 recipe，不执行\nmake -n CFLAGS=-O2     # 配合变量覆盖，预演效果"}},{"h":"用 make -d / --debug 追踪「为什么某目标被认为最新」","s":"当 make 啥也不做（你说该重编却没重编），-d 会逐条打印「X 比 Y 新，跳过」「无配方，跳过」的判断依据。输出很长，通常配合 grep 看具体目标。","c":{"lang":"bash","code":"make -d 2>&1 | grep -i \"main.o\""}},{"h":"用 make -p 打印完整规则库（含隐式规则）","s":"-p 在结束前把所有内置和自定义的显式/隐式规则、变量全打印出来。看某个 .o 到底匹配了哪条规则，靠它最准。","c":{"lang":"bash","code":"make -p -f /dev/null     # 只看内置规则，不读当前 Makefile\nmake -p | grep -A3 \"main.o\"  # 查某目标的规则来源"}},{"h":"用 make -t / --touch 假装构建","s":"只把目标的时间戳更新到「最新」，不真正编译。常用于「我想让 make 暂时认为这些都编过了」，调试依赖图时快速跳过昂贵步骤。","c":{"lang":"bash","code":"make -t            # 把所有目标 touch 成最新\nmake -t clean      # 仅 touch clean（无害）"}},{"h":"用 make -k / --keep-going 一个失败也继续","s":"默认 make 遇到第一个错误就停。多目标构建时用 -k，让它把能编的都编了，最后一次性报所有失败，省去「改一个跑一次」的循环。","c":{"lang":"bash","code":"make -k all"}},{"h":"用 make -w / --print-directory 看目录切换","s":"递归 make（$(MAKE) -C sub）时，-w 打印「进入/离开目录」，定位「某条命令到底在哪个目录跑的」最直观。","c":null},{"h":"用 $(info) / $(warning) / $(error) 插桩变量","s":"在 Makefile 里插一行 $(info CC=$(CC))，解析阶段就打印变量当前值。warning 带文件名行号，error 直接终止（可用于强制检查必填变量）。","c":{"lang":"make","code":"$(info BUILD_DIR=$(BUILD_DIR))\n$(warning CFLAGS is $(CFLAGS))\n# $(error \"CC not set\")  # 需要时取消注释"}},{"h":".DEFAULT 规则兜底未知目标","s":"当 make 遇到一个没有任何规则匹配的目标，会尝试 .DEFAULT 里的 recipe。常用来做「万能编译」或给出友好报错。","c":{"lang":"make","code":".DEFAULT:\n\t@echo \"no rule to make $@\" && exit 1"}},{"h":"$(MAKE) 变量递归调用子 make","s":"父 make 调用子目录时必须用 $(MAKE) 而非裸 make，否则 -j 并行旗标、jobserver 令牌不会下传，子目录退回串行甚至僵死。","c":{"lang":"make","code":"sub:\n\t$(MAKE) -C src        # 正确：透传 -j / jobserver\n#\tmake -C src          # 错误：丢失并行语义"}},{"h":"用 remake -x 反向追踪某产物由哪些规则生成","s":"GNU remake（make 的增强版）的 -x 能打印「这个文件是被哪条规则、因为哪些依赖生成的」，比 -d 易读，适合排查「为什么这个 .o 是旧的」。","c":{"lang":"bash","code":"remake -x main.o"}},{"h":"模式规则与隐式规则的优先级之争","s":"你写的 %.o: %.c 是「模式规则」，make 还有内置的 .c.o: 隐式规则。当两者共存，make 按「后缀规则/模式规则优先级 + 先决条件新旧」选一条，行为未必是你预期的。用 make -p 比对实际命中。","c":null},{"h":"现代构建系统为什么取代手写 Makefile","s":"手写 Makefile 的三座大山：依赖要靠 -MMD 手工维护、跨平台工具链差异大、-j 正确性全凭人写对依赖边。CMake/Meson/Ninja/Bazel 把「依赖探测、增量判定、并行调度」交给工具，开发者只描述「要什么」而非「…","c":null},{"h":"🧑‍💻 程序员视角","s":"Makefile 出问题先 make -n（干跑）看它到底要执行什么命令，再 make -d 看为什么判定某个目标需要重建——90% 的「改了没生效」是依赖没写全（比如只依赖 .c 不依赖 .h）。make -p 能打印完整的规则库（含…","c":null},{"h":"🎓 博士生视角","s":"构建系统的本质是「依赖图 + 增量判定」：Make 用文件时间戳，Ninja 用更精确的依赖记录与并行调度，Bazel 用内容哈希做「可复现构建」。三者演进的方向是「从时间戳到内容哈希」，因为时间戳在分支切换、时钟回拨时会误判。现代 C…","c":null},{"h":"📚 考研者视角","s":"工程岗笔试/面试：","c":null}]}],"exams":[{"kind":"choice","q":"Make 判断「要不要重建」的唯一依据","stem":"给出一条规则 app: main.o util.o。下列哪种情况 Make 不会重新执行 recipe？","opts":[{"k":"A","t":"app 文件不存在"},{"k":"B","t":"main.o 比 app 新"},{"k":"C","t":"util.o 的内容变了，但 mtime 没变"},{"k":"D","t":"main.o 的 mtime 比 app 早，但 util.o 比 app 新"}],"ans":"C","why":"考察对「增量构建判据」这一根基性事实的掌握，是本节第一个必背点。"},{"kind":"fix_error","q":"make clean 什么都不做，还返回成功","stem":"某工程的 Makefile 末尾是： makefile clean: \\trm -f app .o 某天同事在工程根目录建了一个名为 clean 的空文件（可能是误操作，也可能是某个工具生成的）。此后 make clean 输出 'clean' is up to date. 并返回 0，旧的目标文件一直没被删掉。 请指出根因并给出修复。","opts":[],"ans":"根因：clean 与真实文件同名，Make 按普通文件规则比较 mtime——文件 clean 存在且无依赖比它新，于是判定「已是最新」而跳过 recipe。 修复：把动作型目标声明为伪目标。 makefile .PHONY: clean clean: \\trm -f app .o .PHONY 告诉 Make：这个目…","why":"考察 .PHONY 的必要性，属于「不写不会报错、写了才不出事」的典型工程约定。"},{"kind":"output","q":"自动变量 $@ $< $^ $? 的展开结果","stem":"已知目标 app 由 main.o、util.o、log.o 链接得到，且三者的 mtime 都晚于 app。A、B、C 三个自动变量在 recipe 中分别展开为什么？ makefile app: main.o util.o log.o \\t@echo \"A=$@\" \\t@echo \"B=$<\" \\t@echo \"C=$^\" A. A=app B=main.o C=main.o util.o l…","opts":[],"ans":"A","why":"自动变量是 Makefile 写错频率最高的地方，$< 与 $^ 混用会直接表现为一批 undefined reference。"},{"kind":"choice","q":"= 与 := 的求值时机","stem":"makefile A = $(B) B = 1 C := $(D) D = 2 all: \\t@echo \"A=[$(A)] C=[$(C)]\" make 的输出是？","opts":[{"k":"A","t":"A=[1] C=[2]"},{"k":"B","t":"A=[1] C=[]"},{"k":"C","t":"A=[] C=[2]"},{"k":"D","t":"A=[] C=[]"}],"ans":"B","why":"递归展开 vs 立即展开是 Makefile 里最反直觉的一处语义，也是 $(shell) 重复执行这类疑难问题的根因。"},{"kind":"coding","q":"补全 Makefile：模式规则 + 自动依赖 + 双构建模式","stem":"给定工程：src/main.c、src/util.c，头文件 include/util.h 被 util.c 包含。 请写出一个 Makefile，满足： 1. 产出可执行文件 app（均放在 build/ 目录下，源码目录保持干净）。 2. 用模式规则处理 .c → .o，不要逐个写死文件名。 3. 改 include/util.h 后，util.o 必须被重新编译（用 -MMD -MP 自动生…","opts":[],"ans":"makefile CC := gcc SRCS := src/main.c src/util.c OBJS := $(SRCS:src/%.c=build/%.o) DEPS := $(OBJS:.o=.d) TARGET := build/app ifeq ($(MODE),debug) CFLAGS := -std…","why":"这是一道「工程化 Makefile」的合成题，覆盖替换引用、模式规则、自动依赖、双模式与目录隔离五个要点。"},{"kind":"coding","q":"课程表 II（拓扑排序 = Make 的依赖解析）","stem":"给定 numCourses 与先修关系 prerequisites[i] = [a, b]（修 a 前须先修 b），返回一个可行的学习顺序；若存在环则返回空数组。 请用邻接表 + 入度数组（Kahn 算法）实现。","opts":[],"ans":"c #include <stdlib.h> int findOrder(int numCourses, int prerequisites, int prerequisitesSize, int prerequisitesColSize, int returnSize) { int indeg = calloc((si…","why":"把「Make 依赖解析」与「拓扑排序」显式对应起来，是本节最有价值的一次跨知识点连接。"},{"kind":"coding","q":"课程表（判环：构建失败的最常见原因）","stem":"给定 numCourses 与先修关系，判断能否修完全部课程（即依赖图是否无环）。 请写出函数，返回布尔值。","opts":[],"ans":"c #include <stdbool.h> #include <stdlib.h> bool canFinish(int numCourses, int prerequisites, int prerequisitesSize, int prerequisitesColSize) { int indeg = call…","why":"判环与拓扑排序是一体两面；这里刻意把它与构建系统的实际报错对应起来。"}],"works":[{"h":"recipe 用空格缩进 → missing separator","d":"Makefile 的词法规则要求 recipe 行必须以 Tab 开头。 现代编辑器默认「按 Tab 插入 N 个空格」，于是从别处复制的片段必然踩这个坑。 报错原文是 Makefile:5: missing separator. Stop.，且报错行号指向第一条 recipe。 正确做法：把 Makefile 的缩进设为「制表符」…"},{"h":"缺 .PHONY 导致目标被静默跳过","d":"若目录里恰好存在名为 clean / test / all 的文件， Make 会认为该 target「已是最新」，什么都不做并返回 0。这是最恶劣的一类 bug： 无报错、无警告，你以为清理过了，其实旧 .o 还在。规则：所有动作型目标一律 .PHONY。"},{"h":"只声明 .c 依赖、漏掉 .h","d":"util.o: util.c 是不完整的声明。 util.c 通过 #include 依赖 util.h，而 Make 无从知晓（它不做预处理）。 后果：改了头文件不重编，链接成功但行为陈旧，甚至多个 .o 结构体布局不一致导致内存错乱。 正确做法：-MMD -MP 生成 .d 并 -include。"},{"h":"-include 写成 include","d":"首次构建时 .d 文件尚不存在， include 会直接报 No such file or directory 而终止。必须用 -include（减号表示「缺失不算错误」）。"},{"h":"= 里放 $(shell ...) 导致命令重复执行","d":"递归展开变量每次被引用都重新求值。 STAMP = $(shell date +%s) 会在每次 $(STAMP) 出现时都执行一次 date， 得到一个「每次都不一样」的值，让构建变得不可复现。改用 :=。"},{"h":"make -j 并行构建出现随机的产物损坏","d":"根因几乎总是依赖声明不完整， 使两个 recipe 会在无依赖关系的情况下并发访问同一文件。 判定法则：-j1 稳定成功而 -j8 偶尔失败 ⇒ 依赖缺失，不要怀疑编译器。 修法：补全依赖边；生成头文件的规则必须显式声明为依赖。"},{"h":"clean 漏删中间产物","d":"只删 app 不删 .o / .d，下次构建复用陈旧 .o， 于是「make clean && make 居然没修好问题」。clean 必须删掉全部生成物： rm -f $(TARGET) $(OBJS) $(OBJS:.o=.d)。"},{"h":"在链接规则里误用 $<","d":"$< 只代表第一个依赖。 链接规则 $(TARGET): $(OBJS) 里用 $< 只会链上 main.o，其他 .o 全丢， 表现为一堆 undefined reference。链接要用 $^（全部依赖）。"}],"asks":[{"q":"make 靠什么判断一个目标要不要重建？为什么不用内容哈希？","a":"判据只有一条：目标不存在，或任一直接依赖的 mtime 晚于目标。 text 重建 ⟺ ¬exists(target) ∨ ∃p ∈ prereq: mtime(target) < mtime(p) 为什么是 mtime 而不是哈希？ 历史与工程原因： 1. O(1) 的代价：stat 拿 mtime 是元数据读取，几乎免费；哈希要读完整文件内容，对大型二进制产物代价高昂。 2. 1976 年的设…","fu":["如果两台机器的时钟不同步（NFS 场景），增量构建会怎样失效？","touch 为什么能强制触发重编？它改变了什么？"],"tag":"字节跳动/腾讯"},{"q":"为什么 Makefile 的 recipe 行必须用 Tab 开头，用空格会报 missing separator？","a":"因为这是 Make 的词法层规则，不是风格约定。 Make 解析文件时需要区分两类行： - 规则行：target: prerequisites——以冒号分隔，可有前导空格（会被忽略）。 - recipe 行：具体命令——以 Tab 开头。 Make 的解析器看到一个「非规则行」时，判断依据就是首字符是否为 Tab。若是制表符 → 归为 recipe；若是空格 → 既不是合法规则、也不是合法 rec…","fu":["有哪些编辑器/IDE 配置可以避免这个问题？","为什么报错行号常常指向「第一条 recipe」而不是真正的错误行？"],"tag":"美团/腾讯"},{"q":"「改了头文件但 make 没重编」是怎么回事？为什么不能手工维护头文件依赖？","a":"根因：Makefile 里写的是 util.o: util.c，但真实依赖是 util.o: util.c util.h ...。 util.c 通过 #include \"util.h\" 把头部内容文本复制进了预处理输出 .i，所以 util.o 的生成结果取决于头文件。但 Make 不做预处理，它只看你写了什么依赖。 为什么后果严重？ 因为它静默： text 改 util.h -> make 认…","fu":["-MD 与 -MMD 的区别是什么？为什么通常选 -MMD？","为什么 -include 前面必须有减号，用 include 会怎样？"],"tag":"阿里/字节跳动"},{"q":"make -j8 平时很快，偶尔却编出崩溃的二进制，重跑又好了——为什么？","a":"这是依赖声明不完整导致的竞态（race condition）。 make -j 依据依赖图做拓扑排序，只调度「依赖已全部就绪」的目标。所以并行构建的正确性完全取决于依赖图的完整性。 若漏了一条边，两个本无「声明」关系的 recipe 可能被并发执行，而在真实文件系统上它们确实冲突（例如一个在读 gen.h 的同时另一个在生成它）。于是产生中间态损坏的产物。 判定法则（比任何日志分析都可靠）： te…","fu":["为什么「串行成功、并行失败」是依赖缺失的充分证据？","递归 make 为什么会让 -j 失效？$(MAKE) 必须大写的原因是什么？"],"tag":"字节跳动/华为"}]},{"id":"clang-u07","subj":"clang","title":"多文件编译与链接","summary":"","concepts":[{"id":"clang-u07/01-translation-unit-and-linkage","file":"01-translation-unit-and-linkage.md","title":"翻译单元、声明与定义、链接属性","kind":"compare","secs":[{"h":"1. 从源码到可执行：谁负责哪一段","s":"C 的编译流程里，每个 .c 文件（更准确说，每个经过预处理的 .c）都是一个独立的翻译单元。","c":{"lang":"text","code":"main.c ──预处理──> main.i ──编译──> main.o ─┐\n                                            ├─链接器──> app.exe\nutil.c ──预处理──> util.i ──编译──> util.o ─┘"}},{"h":"2. 声明 vs 定义","s":"函数「定义」天然也是「声明」。变量的坑更多：int x; 在文件作用域既是定义（试探性定义，","c":{"lang":"c","code":"/* bad.h —— 灾难 */\nint count;          /* 每个包含它的 .c 都产生一个定义 → multiple definition */"}},{"h":"3. 链接属性（linkage）：名字在哪个「作用域」里可见","s":"C 标准定义了三种链接属性，它决定多个翻译单元里的同名标识符是否指同一个实体：","c":{"lang":"c","code":"static int helper(void);        /* 内部链接：别的 .c 里即使声明也链不到 */\nint api_function(void);         /* 外部链接：可以被别的 .c 调用 */"}},{"h":"4. 头文件里到底该放什么","s":"struct 定义放头文件是合法的：类型定义不产生符号、不分配存储（除非实例化对象）。","c":null},{"h":"5. 工程实践：一个模块的标准形态","s":"","c":{"lang":"text","code":"math/\n├── math.h        # 公开接口：声明 + 类型 + 宏\n├── math_internal.h  # 内部共享（不对外）\n└── math.c        # 实现；私有函数加 static"}}]},{"id":"clang-u07/02-symbol-table-and-name-mangling","file":"02-symbol-table-and-name-mangling.md","title":"符号表、目标文件与名称修饰","kind":"flow","secs":[{"h":"1. 目标文件里有什么","s":".o（ELF/PE-COFF 目标文件）不是「机器码的压缩包」，而是一个带符号表的待拼接件：","c":null},{"h":"2. 用 nm 读符号表","s":"nm 输出的每个符号，第一个字母是符号类型，大写=外部链接，小写=内部链接：","c":{"lang":"text","code":"$ nm util.o\n0000000000000000 T add          <- add 在本文件已定义，外部链接\n                 U printf       <- 待链接器从 C 运行库解析\n0000000000000004 d counter      <- static 变量，内部链接（小写 d）"}},{"h":"3. C++ 名称修饰（name mangling）","s":"C 没有重载，函数名直接就是符号名。C++ 有重载、命名空间、模板，所以编译器必须把类型信息","c":{"lang":"cpp","code":"int  add(int, int);\ndouble add(double, double);"}},{"h":"4. 名字修饰带来的 ABI 问题","s":"符号名里编码了签名，所以：","c":null},{"h":"5. 排障工具速查","s":"","c":null},{"h":"6. 工程实践","s":"","c":null}]},{"id":"clang-u07/03-static-and-dynamic-linking","file":"03-static-and-dynamic-linking.md","title":"静态库、动态库与链接顺序","kind":"stack","secs":[{"h":"1. .o → .a：静态库只是「一堆目标文件的归档」","s":"静态库不是新格式，它就是 ar 打包的 .o 集合，加了一个索引方便查找：","c":{"lang":"text","code":"ar rcs libmath.a add.o mul.o      # r=插入 c=创建 s=建立索引"}},{"h":"2. 动态库：把链接推迟到加载期","s":"-fPIC（Position Independent Code）是共享库的必要条件：库会被映射到任意地址，","c":{"lang":"text","code":"gcc -shared -fPIC -o libmath.so add.o mul.o    # Linux\ngcc -shared -o math.dll add.o mul.o            # Windows (MinGW)\ngcc main.c -L. -lmath -o app                   # 链接期只记录依赖"}},{"h":"3. 链接顺序敏感性（面试高频，也是真实故障源）","s":"链接器从左到右扫描命令行，维护一个「未解析符号集合」：","c":{"lang":"bash","code":"gcc main.o -lmath -lutil -o app     # util 依赖 math，但 math 已在 util 之前被扫描过"}},{"h":"4. 常见误区的澄清","s":"同名符号可能被先加载的库抢占（符号插入 / symbol interposition）。","c":null},{"h":"5. 工程实践","s":"","c":null}]},{"id":"clang-u07/04-strong-weak-symbols-and-diagnostics","file":"04-strong-weak-symbols-and-diagnostics.md","title":"强符号、弱符号与链接期排障","kind":"timeline","secs":[{"h":"1. 强符号与弱符号","s":"链接器对多重定义的处理不是一刀切报错，而是按符号强度排序：","c":{"lang":"c","code":"__attribute__((weak)) int config_value = 0;   /* 可被用户模块的强定义覆盖 */"}},{"h":"2. 未定义符号的诊断流程","s":"按顺序问四个问题：","c":{"lang":"text","code":"undefined reference to `add'"}},{"h":"3. 递增诊断的三件套","s":"","c":null},{"h":"4. 循环依赖与静态库的陷阱","s":"两个静态库互相引用时，无论怎么排序都会有一个「先被扫描而无成员被抽取」：","c":{"lang":"text","code":"liba.a 里的 f() 调用 libb.a 的 g()；libb.a 里的 h() 调用 liba.a 的 f()\n$ gcc main.o -la -lb      # 扫描 liba 时 g 还未被引用 → liba 无成员抽取；libb 需要 f 时 liba 已过\nundefined reference to `g'"}},{"h":"5. 头文件递归包含与循环包含","s":"包含守卫能让它不无限展开，但会带来顺序依赖：先包含谁，决定谁的类型先可见。","c":{"lang":"c","code":"/* a.h */ #include \"b.h\"\n/* b.h */ #include \"a.h\"     /* 互相包含 */"}},{"h":"6. 工程实践清单","s":"","c":null}]},{"id":"clang-u07/05-linking-practical-recipes","file":"05-linking-practical-recipes.md","title":"多文件编译与链接实战手记：凯喵和 undefined reference 缠斗的十二个夜晚","kind":"flow","secs":[{"h":"开场：链接错误为什么比编译错误难查","s":"编译错误指到行、给出类型不匹配的原因；链接错误只给你一句 undefined reference to 'foo'，不告诉你为什么找不到。","c":{"lang":"c","code":"/* util.h */\nint add(int a, int b);        /* 只有声明 */\n\n/* main.c */\n#include \"util.h\"\nint main(void) { return add(1, 2); }"}},{"h":"收尾：凯喵的链接排查口诀","s":"五句话应付九成情况：","c":null}]}],"exams":[{"kind":"choice","q":"编译错误还是链接错误","stem":"下面两个报错分别发生在哪个阶段，根因是什么？ ① error: implicit declaration of function 'add' ② undefined reference to 'add'","opts":[{"k":"A","t":"都是链接错误"},{"k":"B","t":"① 编译错误（缺声明）② 链接错误（缺定义）"},{"k":"C","t":"① 链接错误（缺声明）② 编译错误（缺定义）"},{"k":"D","t":"都是编译错误"}],"ans":"B","why":"考察对「编译期/链接期职责边界」的理解，是本节最核心的一条线。"},{"kind":"choice","q":"文件作用域 static 与块作用域 static","stem":"下列关于 static 的说法，正确的是（多选）：","opts":[{"k":"A","t":"文件作用域的 static int n; 具有内部链接，其他翻译单元无法引用"},{"k":"B","t":"块作用域的 static int n; 具有内部链接，跨函数共享"},{"k":"C","t":"块作用域的 static int n; 具有静态存储期，但无链接"},{"k":"D","t":"文件作用域的 static 函数无法被本翻译单元以外的代码调用"}],"ans":"ACD","why":"考察 static 的双重语义（内部链接 vs 静态存储期），极易混淆。"},{"kind":"fix_error","q":"修复头文件里的多重定义","stem":"以下代码在 gcc main.c other.c -o app 时报 multiple definition of 'counter'，请指出根因并给出最小修复。 c / config.h / #ifndef CONFIG_H #define CONFIG_H int counter = 0; / 第 4 行 / #endif c / main.c / #include \"config.h\" in…","opts":[],"ans":"把定义移到某个 .c，头文件只留 extern 声明","why":"把「包含守卫的作用边界」和「强符号多重定义」两件事合起来考。"},{"kind":"coding","q":"多文件工程：Trie 的接口与实现分离","stem":"把「实现 Trie（前缀树）」拆成标准的三文件工程：trie.h（只放结构体声明与函数声明）、trie.c（实现，内部辅助函数一律 static）、main.c（只包含头文件并调用）。 要求： 1. trie.h 中不得出现任何函数定义或变量定义，且能被单独包含并通过编译。 2. trie.c 的内部辅助函数使用 static，用 nm trie.o 验证它们是小写 t（内部链接）。 3. 用 g…","opts":[],"ans":"","why":"把算法题改造成真实工程结构，训练接口/实现分离与 static 的使用纪律。"},{"kind":"coding","q":"静态库：把并查集打包成 libdsu.a","stem":"参考 GitHub 上的并查集实现（题面见链接），把并查集封装成静态库并使用： 1. dsu.c 实现 dsu_init / dsu_find（路径压缩）/ dsu_union（按秩合并）。 2. 用 ar rcs libdsu.a dsu.o 打包。 3. main.c 通过 -L. -ldsu 链接，实现 10 个元素的两组合并与连通性查询。 4. 用 nm libdsu.a 查看归档内各成员…","opts":[],"ans":"","why":"静态库打包 + 按需抽取 + 模块私有状态的 static 封装，是工程化必练。"},{"kind":"coding","q":"动态库与 extern \"C\" 接口","stem":"把一段字符串处理逻辑（如最长回文子串，参考牛客字符串专题，题面见链接）编译成动态库，并用 extern \"C\" 暴露纯 C 接口，供 C 主程序调用： 1. 用 g++ 编译 libstr.dll（-shared）。 2. 头文件用 #ifdef __cplusplus extern \"C\" { #endif 包裹声明。 3. 用 nm -C 对比加与不加 extern \"C\" 时符号名差异（_Z…","opts":[],"ans":"","why":"extern \"C\" 是 C/C++ 混编的唯一桥梁，必须能用 nm 实证其效果。"},{"kind":"output","q":"数出这条链接命令会报几个 undefined reference","stem":"三个目标文件的符号表如下（T 已定义于代码段、U 引用但未定义）： main.o : U add, U mul, T main util.o : T add, T sub math.o : T mul, U sub 若链接命令误写成 gcc main.o math.o -o app（漏掉 util.o），链接器最终报出的 undefined reference 符号有几个？请输出个数。","opts":[],"ans":"2","why":"引用集减定义集 = {add, sub}，共 2 个。"}],"works":[{"h":"把头文件当「公共变量区」","d":"在 .h 里写 int counter;，被 N 个 .c 包含就产生 N 个定义。 现代 GCC 默认 -fno-common，直接 multiple definition。正确做法：头文件写 extern int counter;， 在某一个 .c 里写 int counter = 0;。"},{"h":"extern int x = 1; 当声明用","d":"带初始化器的 extern 仍然是定义，不是声明。 放在头文件里同样导致重复定义。声明不允许带初始化器。"},{"h":"该加 static 的内部函数没加","d":"两个模块各自实现 init()，链接期撞名。 凡不对外暴露的函数/文件作用域变量一律加 static：既是封装，也避免污染全局符号空间。"},{"h":"undefined reference 时误改代码","d":"这是链接期错误，去改语法/声明是无用功。 先 nm 看符号是否存在，再查链接命令行是否漏了 .o 或库。"},{"h":"静态库链接顺序颠倒","d":"被依赖的库写在前面会被「扫描过就忘掉」。 规则：调用者在前、被调用者在后；循环依赖用 -Wl,--start-group ... --end-group。"},{"h":"以为 -l 写了就一定会链进来","d":"静态库只有在「有成员能解决当前未解析符号」时才会被抽取。 若主程序没直接引用库内符号（只在库内部互相引用），需 --whole-archive。"},{"h":"C/C++ 混编忘记 extern \"C\"","d":"C++ 侧把 int add(int,int) 修饰成 _Z3addii， 与 C 目标的 add 对不上，报 undefined reference to '_Z3addii'。 头文件里用 #ifdef __cplusplus extern \"C\" { #endif 包裹。"},{"h":"头文件循环包含","d":"有包含守卫时不会无限展开，但会造成「类型可见性依赖包含顺序」的隐蔽 bug。 用前置声明（struct X;）或抽出无依赖的 types.h 打破环。"}],"asks":[{"q":"为什么头文件里不能放函数定义和变量定义？","a":"头文件是被文本包含进每个 .c 的，每个包含它的 .c 都会各自产生一份定义。 - 函数定义：普通函数是外部链接的强符号，多个翻译单元各有一份 → 链接期multiple definition。例外是 static inline（每个 TU 一份内部链接副本，合法）；C99 的 inline 语义更绕（需要 extern 声明在某个 TU 里给出唯一定义）。 - 变量定义：int x = 1; 是…","fu":["static const int N = 10; 放头文件合法吗？和 extern const int N; 有何区别？","C++ 里为什么 inline 函数可以放头文件？它和 C 的 static inline 有什么不同？"],"tag":"腾讯/字节跳动"},{"q":"undefined reference 和 implicit declaration 有什么本质区别？怎么系统性排查？","a":"阶段不同、工具不同、修法不同。 | | implicit declaration | undefined reference | |---|---|---| | 报出者 | 编译器（cc1） | 链接器（ld） | | 含义 | 本 TU 内看不到该名字的声明 | 全程序范围内找不到该符号的定义 | | 修法 | 包含头文件 / 补原型 / 查声明拼写 | 补 .o、调库顺序、查 static、查…","fu":["如果声明是 void f(int) 而定义是 void f(double)，链接器会报错吗？为什么？","nm 输出里的 U、T、t、B、D 分别代表什么？"],"tag":"腾讯/阿里巴巴"},{"q":"静态库和动态库怎么选？为什么链接器对 -l 的顺序敏感？","a":"选型维度： | 维度 | 静态库 .a | 动态库 .so/.dll | |---|---|---| | 部署 | 单文件，零负担 | 需带库 / 设搜索路径 | | 体积 | 大（代码被复制） | 小 | | 内存共享 | 无 | 多进程共享同一份代码页 | | 升级 | 需重新链接 | 替换库文件即可 | | 插件化 | 不支持 | 支持（dlopen/LoadLibrary） | 经验法则：…","fu":["-fPIC 解决的是什么问题？不加会怎样？","动态库的符号插入（symbol interposition）是什么？怎么避免？"],"tag":"华为/腾讯"},{"q":"C++ 的 name mangling 是什么？为什么它让 C++ 的 ABI 这么脆弱？","a":"是什么：C++ 支持重载、命名空间、模板，链接器只能按纯符号名做匹配，所以编译器必须把类型信息编码进符号名（Itanium ABI 下形如 _Z3addii：_Z + 名字长度 + 名字 + 参数类型编码）。它把重载决议的结果提前固化到符号名里。 后果：符号名编码了签名，因此改参数类型（即使语义等价，如 int → int32_t 在某些平台上不同）、改命名空间、改 const/引用修饰，都会改变…","fu":["nm 和 nm -C 有什么区别？什么时候必须用 -C？","extern \"C\" 能包裹 C++ 的类定义吗？为什么？"],"tag":"腾讯/字节跳动"}]}];

